  function actionGift(id){
    if(!canAct())return;
    const c=findC(id);if(!c)return;
    state._giftTarget=id;
    let html='<div style="text-align:center;margin-bottom:12px;">';
    html+=portraitHTML(c.portraitIdx,60,80,c.princessPortrait);
    html+='<div style="font-size:16px;font-weight:bold;color:#c49030;margin-top:6px;">选择赠送给 '+c.name+' 的礼物</div>';
    html+='</div>';
    html+='<div style="display:flex;flex-direction:column;gap:6px;max-height:50vh;overflow-y:auto;padding:4px;">';
    GIFT_LIST.forEach(function(g,i){
      var canBuy=state.treasury>=g.price;
      var parts=[];
      if(g.favor>0)parts.push('宠爱+'+g.favor);
      if(g.power>0)parts.push('势力+'+g.power);
      if(g.health>0)parts.push('健康+'+g.health);
      if(g.talent>0)parts.push('才华+'+g.talent);
      if(g.wisdom>0)parts.push('智力+'+g.wisdom);
      html+='<button class="gift-item'+(canBuy?'':' gift-disabled')+'" onclick="'+(canBuy?'Game.confirmGift('+i+')':'')+'" '+(canBuy?'':'disabled')+'>';
      html+='<div class="gift-left"><span class="gift-icon">'+g.icon+'</span><span class="gift-name">'+g.name+'</span></div>';
      html+='<div class="gift-right"><span class="gift-price">'+g.price+'两</span><span class="gift-desc">'+parts.join('，')+'</span></div>';
      html+='</button>';
    });
    html+='</div>';
    html+='<button class="btn-secondary" style="margin-top:12px;width:100%;" onclick="Game.cancelGift()">取消</button>';
    document.getElementById('gift-select-content').innerHTML=html;
    tryOpenModal(function(){document.getElementById('modal-gift-select').classList.add('show');});
  }

  function confirmGift(idx){
    const g=GIFT_LIST[idx];if(!g)return;
    const c=findC(state._giftTarget);if(!c)return;
    if(state.treasury<g.price){showFeedback('国库不足！');return;}
    state.treasury-=g.price;
    c.favor=clamp(c.favor+g.favor,0,2200);
    c.power=clamp(c.power+g.power,0,500);
    c.health=clamp(c.health+g.health,0,100);
    if(c.talent===undefined)c.talent=50;
    c.talent=clamp(c.talent+g.talent,0,100);
    if(c.wisdom===undefined)c.wisdom=50;
    c.wisdom=clamp(c.wisdom+g.wisdom,0,100);
    const rc=checkRankChange(c);
    consumeAction();save();updateUI();
    let msg='赠送 <span class="pos">'+g.name+'</span> 给 '+c.name+'<br>';
    var changes=[];
    if(g.favor>0)changes.push('宠爱 <span class="pos">+'+g.favor+'</span>');
    if(g.power>0)changes.push('势力 <span class="pos">+'+g.power+'</span>');
    if(g.health>0)changes.push('健康 <span class="pos">+'+g.health+'</span>');
    if(g.talent>0)changes.push('才华 <span class="pos">+'+g.talent+'</span>');
    if(g.wisdom>0)changes.push('智力 <span class="pos">+'+g.wisdom+'</span>');
    msg+=changes.join('，')+'<br>国库 <span class="neg">-'+g.price+'</span>两<br>行动 <span class="neg">-1</span>';
    if(rc){msg+='<br>势力满足条件，<span class="pos">'+c.name+' 晋升为 '+rc.rank+'</span>';}
    showFeedback(msg);
    document.getElementById('modal-gift-select').classList.remove('show');
    closeModal();
    delete state._giftTarget;
    showDetail(c.id);
  }

  function cancelGift(){
    document.getElementById('modal-gift-select').classList.remove('show');
    closeModal();
    delete state._giftTarget;
  }

  function actionCold(id){if(!canAct())return;const c=findC(id);if(!c)return;if(!confirm('&#30830;&#23450;&#23558; '+c.name+' &#25171;&#20837;&#20919;&#23467;&#65281;'))return;c.health=clamp(c.health-30,0,100);c.power=clamp(c.power-30,0,500);state.concubines=state.concubines.filter(x=>x.id!==id);state.coldPalaceList.push(c);consumeAction();delete state.banned[id];save();updateUI();showFeedback('<span class="neg">'+c.name+'</span> &#25171;&#20837;&#20919;&#23467;<br>&#20581;&#24247; <span class="neg">-30</span>&#65292;&#21183;&#21147; <span class="neg">-30</span>&#65288;&#24403;&#21069;'+c.health+'&#65289;<br>&#34892;&#21160; <span class="neg">-1</span>');showPage('main');}

  function actionKill(id){if(!canAct())return;const c=findC(id);if(!c)return;showExecutionSelect(id,false,true);}

  // ===== 赐死方式选择 =====
  function showExecutionSelect(id,coldPalace,consumeAction,eventCtx){
    const c=coldPalace?state.coldPalaceList.find(x=>x.id===id):state.concubines.find(x=>x.id===id);
    if(!c)return;
    state._executeTarget=id;
    state._executeCold=!!coldPalace;
    state._executeAction=!!consumeAction;
    state._executeMethod=null;
    state._executeEventCtx=eventCtx||null;
    document.getElementById('execute-target-info').innerHTML=c.portraitIdx?portraitHTML(c.portraitIdx,60,76,c.princessPortrait):'';
    document.getElementById('execute-target-info').innerHTML+='<div style="font-size:15px;font-weight:bold;color:#5a3e28;margin-top:8px;">'+c.name+'</div>';
    document.getElementById('execute-target-info').innerHTML+='<div style="font-size:12px;color:#9060c0;">'+(c.title?c.title+c.rank:c.rank)+' · '+c.personality.name+'</div>';
    let grid='';
    EXECUTION_METHODS.forEach(function(m,i){
      grid+='<div class="exec-method-card" id="exec-card-'+i+'" onclick="Game.selectExecution('+i+')"><div class="exec-icon">'+m.icon+'</div><div class="exec-name">'+m.name+'</div><div class="exec-desc">'+m.desc+'</div></div>';
    });
    document.getElementById('execute-method-grid').innerHTML=grid;
    document.getElementById('execute-confirm-btn').disabled=true;
    document.getElementById('modal-execute').classList.add('show');
  }
  function selectExecution(idx){
    state._executeMethod=idx;
    for(var i=0;i<EXECUTION_METHODS.length;i++){
      var card=document.getElementById('exec-card-'+i);
      if(card)card.className='exec-method-card'+(i===idx?' selected':'');
    }
    document.getElementById('execute-confirm-btn').disabled=false;
  }
  function closeExecutionSelect(){
    document.getElementById('modal-execute').classList.remove('show');
    state._executeTarget=null;state._executeCold=false;state._executeAction=false;state._executeMethod=null;state._executeVictimInfo=null;state._executeColdReply=null;state._executeEventCtx=null;state._executeSceneState=null;
  }

  // ===== 临死反应 =====
  function showDeathReaction(){
    var id=state._executeTarget;
    if(!id)return;
    var c=state._executeCold?state.coldPalaceList.find(x=>x.id===id):state.concubines.find(x=>x.id===id);
    if(!c){closeExecutionSelect();return;}
    // Save concubine info for death scene (in case they're removed before scene is viewed)
    state._executeVictimInfo=state._executeVictimInfo||{};
    state._executeVictimInfo._concubineSnapshot={name:c.name,rank:c.rank,title:c.title||'',personality:c.personality?c.personality.name:'温婉',portraitIdx:c.portraitIdx,health:c.health,princessPortrait:c.princessPortrait||''};
    var method=EXECUTION_METHODS[state._executeMethod];
    var pname=c.personality?c.personality.name:'温婉';
    var reactions=DEATH_REACTIONS[pname]||DEATH_REACTIONS['温婉'];
    var quote=reactions[method.name]||'……臣妾领死。';
    var html='<div style="text-align:center;">';
    if(c.portraitIdx){
      html+=portraitHTML(c.portraitIdx,80,80,c.princessPortrait);
    }
    html+='<div class="reaction-name">'+c.name+'</div>';
    html+='<div class="reaction-personality">'+(c.title?c.title+c.rank:c.rank)+' · '+pname+'</div>';
    html+='<div class="reaction-method-tag">赐死方式：'+method.icon+' '+method.name+'</div>';
    html+='<div class="reaction-quote">'+quote+'</div>';
    html+='<button class="btn-primary" onclick="Game.showDeathScene()">&#36176;&#27515;&#22330;&#26223;</button>';
    html+='</div>';
    document.getElementById('reaction-content').innerHTML=html;
    document.getElementById('modal-execute').classList.remove('show');
    document.getElementById('modal-reaction').classList.add('show');
  }
  function closeDeathReaction(){
    document.getElementById('modal-reaction').classList.remove('show');
  }

  // ===== 赐死场景弹窗 =====
  function showDeathScene(){
    var id=state._executeTarget;
    if(!id)return;
    var method=EXECUTION_METHODS[state._executeMethod]||{name:'赐死'};
    // Get concubine info: try live data first, then snapshot
    var c=state._executeCold?state.coldPalaceList.find(x=>x.id===id):state.concubines.find(x=>x.id===id);
    var snap=(state._executeVictimInfo&&state._executeVictimInfo._concubineSnapshot)||null;
    var name=c?c.name:(snap?snap.name:'妃子');
    var rank=c?c.rank:(snap?snap.rank:'');
    var title=c?(c.title||''):(snap?snap.title:'');
    var pname=c?(c.personality?c.personality.name:'温婉'):(snap?snap.personality:'温婉');
    var portraitIdx=c?c.portraitIdx:(snap?snap.portraitIdx:0);
    var princessPortrait=c?(c.princessPortrait||''):(snap?snap.princessPortrait||'':'');
    var methodName=method.name;

    var evt=state._executeEventCtx;
    var html='';

    if(evt&&DEATH_SCENES.event&&DEATH_SCENES.event[evt.eventType]&&DEATH_SCENES.event[evt.eventType][methodName]){
      // 事件赐死
      var scene=DEATH_SCENES.event[evt.eventType][methodName];
      var v=evt.vars||{};
      function rep(s){return s.replace(/\{perpName\}/g,v.perpName||'').replace(/\{victimName\}/g,v.victimName||'').replace(/\{year\}/g,v.year||'').replace(/\{month\}/g,v.month||'').replace(/\{victimPregMonth\}/g,v.victimPregMonth||'');}
      html+='<div class="death-scene-module"><div class="death-scene-title">&#128220; 事件回顾</div><div class="death-scene-text">'+rep(scene.review)+'</div></div>';
      html+='<div class="death-scene-module"><div class="death-scene-title">&#9201; 临刑时刻</div><div class="death-scene-text">'+rep(scene.moment)+'</div></div>';
      html+='<div class="death-scene-module"><div class="death-scene-title">&#9876; 赐死过程</div><div class="death-scene-text">'+rep(scene.process)+'</div></div>';
      html+='<div class="death-scene-module"><div class="death-scene-title">&#127749; 临终画面</div><div class="death-scene-text">'+rep(scene.afterimage)+'</div></div>';
      // 涉事妃反应
      if(v.perpName){
        var perpReact=getConcubineDeathReact(pname);
        html+='<div class="death-scene-module"><div class="death-scene-title">&#128142; 涉事妃嫔反应</div>';
        html+='<div class="death-involved-item"><strong>'+v.perpName+'</strong> <span style="color:#9060c0;font-size:11px;">（'+(v.perpPname||pname)+'）</span><br><span style="font-size:13px;color:#5a3e28;line-height:1.8;">'+perpReact+'</span></div>';
        // 有真实妃子受害者的事件才显示受害者反应
        var hasVictim=['暗中下毒','谋害皇嗣','暗害子嗣','暗算陷害','孕期风波'];
        if(hasVictim.indexOf(evt.eventType)!==-1 && v.victimName){
          var victimReact=getVictimDeathReact(v.victimPname||'温婉');
          html+='<div class="death-involved-item"><strong>'+v.victimName+'</strong> <span style="color:#9060c0;font-size:11px;">（受害者）</span><br><span style="font-size:13px;color:#5a3e28;line-height:1.8;">'+victimReact+'</span></div>';
        }
        // 无妃子受害者的事件，显示后宫其他妃嫔反应
        var noVictim=['私通败露','母家获罪','克扣用度','争风吃醋'];
        if(noVictim.indexOf(evt.eventType)!==-1){
          var otherReact=getOtherConcubinesReact(pname);
          if(otherReact.length>0){
            html+='</div>';
            html+='<div class="death-scene-module"><div class="death-scene-title">&#128142; 后宫其他妃反应</div>';
            otherReact.forEach(function(r){
              html+='<div class="death-involved-item"><strong>'+r.name+'</strong> <span style="color:#9060c0;font-size:11px;">（'+r.pname+'）</span><br><span style="font-size:13px;color:#5a3e28;line-height:1.8;">'+r.react+'</span></div>';
            });
          }
        }
        html+='</div>';
      }
    } else {
      // 普通赐死
      var sceneKey=pname;
      var normalScenes=DEATH_SCENES.normal;
      var scene=(normalScenes[sceneKey]&&normalScenes[sceneKey][methodName])||(normalScenes['温婉']&&normalScenes['温婉'][methodName]);
      if(scene){
        if(scene.moment)html+='<div class="death-scene-module"><div class="death-scene-title">&#9201; 临刑时刻</div><div class="death-scene-text">'+scene.moment+'</div></div>';
        if(scene.process)html+='<div class="death-scene-module"><div class="death-scene-title">&#9876; 赐死过程</div><div class="death-scene-text">'+scene.process+'</div></div>';
        if(scene.afterimage)html+='<div class="death-scene-module"><div class="death-scene-title">&#127749; 临终画面</div><div class="death-scene-text">'+scene.afterimage+'</div></div>';
      } else {
        // Fallback: method-only description
        html+='<div class="death-scene-module"><div class="death-scene-title">&#9876; 赐死过程</div><div class="death-scene-text">'+name+'被'+methodName+'，悄然离世。</div></div>';
      }
      // 宫人议论
      html+='<div class="death-scene-module"><div class="death-scene-title">&#128172; 宫人议论</div>';
      var servantReact=getServantDeathReact(pname,methodName);
      html+='<div class="death-involved-item"><span style="font-size:13px;color:#5a3e28;line-height:1.8;">'+servantReact+'</span></div>';
      html+='</div>';
      // 其他妃嫔看法（只在宫中有其他妃嫔时显示）
      var otherReact=getOtherConcubinesReact(pname);
      if(otherReact.length>0){
        html+='<div class="death-scene-module"><div class="death-scene-title">&#128142; 妃嫔看法</div>';
        otherReact.forEach(function(r){
          html+='<div class="death-involved-item"><strong>'+r.name+'</strong> <span style="color:#9060c0;font-size:11px;">（'+r.pname+'）</span><br><span style="font-size:13px;color:#5a3e28;line-height:1.8;">'+r.react+'</span></div>';
        });
        html+='</div>';
      }
    }

    document.getElementById('death-scene-header').innerHTML='&#36176;&#27515;'+(title?title:'')+name;
    document.getElementById('death-scene-content').innerHTML=html;
    document.getElementById('modal-reaction').classList.remove('show');
    document.getElementById('modal-death-scene').classList.add('show');
  }
  function closeDeathScene(){
    document.getElementById('modal-death-scene').classList.remove('show');
    executeDeath();
  }

