  function getOtherConcubinesReact(victimPname){
    // Only generate reactions from actual living concubines — no generic fakes
    var living=state.concubines.filter(function(x){return x.id!==state._executeTarget;});
    var reactions=[];
    var count=Math.min(3,living.length);
    for(var i=0;i<count;i++){
      var lc=living[i];
      var lp=lc.personality?lc.personality.name:'温婉';
      var react=getSingleConcubineReact(lp,victimPname);
      reactions.push({name:lc.rank+lc.name,pname:lp,react:react});
    }
    return reactions;
  }
