  function openBed(){
    if(state.concubines.length===0){showFeedback('后宫空无一人，无法翻牌！');return;}
    if(state.pendingEvent){showFeedback('请先处理后宫异动事件！');return;}
    if(state.actionsLeft<=0){showFeedback('本月行动已用完！');return;}
    if(state._bedTarget){showFeedback('请先完成当前侍寝！');return;}
    state._bedTarget=null;
    state._bedFlipping=false;
    const available=state.concubines.filter(c=>!c.pregnant);
    if(available.length===0){showFeedback('后宫妃子皆在孕期，不宜侍寝！');return;}
    const pool=[...available].sort(()=>Math.random()-0.5).slice(0,3);
    state._bedPool=pool;
    let html='<div style="text-align:center;">';
    html+='<p style="color:#a08060;font-size:13px;margin-bottom:16px;">请皇上翻牌，选择今夜侍寝的妃子</p>';
    html+='<div style="display:flex;justify-content:center;flex-wrap:wrap;">';
    pool.forEach((c,i)=>{
      html+=`<div class="bed-card" id="bed-card-${i}" onclick="Game.flipCard(${i})"><div class="bed-card-inner">翻<br>牌</div></div>`;
    });
    html+='</div></div>';
    document.getElementById('bed-select-content').innerHTML=html;
    tryOpenModal(()=>{document.getElementById('modal-bed-select').classList.add('show');});
    consumeAction();
  }

  function flipCard(idx){
    if(state._bedFlipping)return;
    state._bedFlipping=true;
    const c=state._bedPool[idx];if(!c){state._bedFlipping=false;return;}
    state._bedTarget=c.id;
    const el=document.getElementById('bed-card-'+idx);
    el.classList.add('revealed');
    el.innerHTML=`${portraitHTML(c.portraitIdx,70,90,c.princessPortrait)}<div style="margin-top:6px;font-weight:bold;color:#5a3e28;">${c.title?c.title+c.rank:c.name}</div>`;
    setTimeout(()=>{
      document.getElementById('modal-bed-select').classList.remove('show');
      triggerBedIntercept(c);
      state._bedFlipping=false;
    },1500);
  }

  // ===== 中途截宠 =====
  function triggerBedIntercept(c){
    if(Math.random()>0.30){showBedDialogue(c);return;}
    const interceptors=state.concubines.filter(x=>x.id!==c.id&&x.talent>=60&&!state.banned[x.id]);
    const schemeTypes=['心机','娇媚','风情婉约','小气善妒','虚荣攀比'];
    const eligible=interceptors.filter(x=>{const pn=x.personality?x.personality.name:'';return schemeTypes.includes(pn);});
    const pool=eligible.length>0?eligible:interceptors;
    if(pool.length===0){showBedDialogue(c);return;}
    const rival=pick(pool);
    const arts=pick(['一阵歌声','一曲琴声','一阵笛音','一段舞步']);
    state._bedIntercept={target:c,rival:rival};
    let html='<div style="text-align:center;">';
    html+=`<p style="color:#a08060;font-size:13px;margin-bottom:16px;">皇上正前往 ${c.rank}${c.name} 宫中的路上，忽闻${arts}从别处传来。太监小声提醒："启禀皇上，那是 ${rival.rank}${rival.name} 宫中传来的……"</p>`;
    html+='<div style="display:flex;flex-direction:column;gap:8px;">';
    html+=`<button class="btn-option" onclick="Game.bedInterceptChoice(0)">循声而去（改宠${rival.name}）</button>`;
    html+=`<button class="btn-option" onclick="Game.bedInterceptChoice(1)">径直前往${c.name}宫中</button>`;
    html+=`<button class="btn-option" onclick="Game.bedInterceptChoice(2)">先听一曲再走</button>`;
    html+='</div></div>';
    document.getElementById('bed-dialogue-content').innerHTML=html;
    document.getElementById('modal-bed-dialogue').classList.add('show');
  }

  function bedInterceptChoice(idx){
    const data=state._bedIntercept;if(!data)return;
    const c=data.target,rival=data.rival;
    delete state._bedIntercept;
    document.getElementById('modal-bed-dialogue').classList.remove('show');
    if(idx===0){
      c.favor=clamp(c.favor-20,0,2200);rival.favor=clamp(rival.favor+25,0,2200);
      if(!c.favors)c.favors={};if(!rival.favors)rival.favors={};
      c.favors[rival.id]=(c.favors[rival.id]||0)-15;
      rival.favors[c.id]=(rival.favors[c.id]||0)-5;
      if(c.grudge&&c.grudge.targetId===rival.id){c.grudge.intensity=clamp((c.grudge.intensity||0)+15,0,100);}
      else if(c.favors[rival.id]<-10){c.grudge={targetId:rival.id,intensity:20};}
      logEvent('中途截宠','改宠'+rival.name);save();updateUI();
      showFeedback(`循声而去，改宠 <span class="pos">${rival.name}</span><br>${c.name} 宠爱 <span class="neg">-20</span>，${rival.name} 宠爱 <span class="pos">+25</span>`);
      state._bedTarget=rival.id;
      showBedDialogue(rival);
    } else if(idx===1){
      c.favor=clamp(c.favor+20,0,2200);rival.favor=clamp(rival.favor-10,0,2200);
      if(!rival.favors)rival.favors={};
      rival.favors[c.id]=(rival.favors[c.id]||0)-10;
      if(rival.grudge&&rival.grudge.targetId===c.id){rival.grudge.intensity=clamp((rival.grudge.intensity||0)+10,0,100);}
      else if(rival.favors[c.id]<-10){rival.grudge={targetId:c.id,intensity:15};}
      logEvent('中途截宠','不改'+c.name);save();updateUI();
      showFeedback(`不为所动，径直前往 <span class="pos">${c.name}</span> 宫中<br>${c.name} 宠爱 <span class="pos">+20</span>，${rival.name} 宠爱 <span class="neg">-10</span>`);
      showBedDialogue(c);
    } else {
      c.favor=clamp(c.favor+10,0,2200);rival.favor=clamp(rival.favor+10,0,2200);
      logEvent('中途截宠','两边都宠');save();updateUI();
      showFeedback(`先听一曲再走<br>${c.name}、${rival.name} 各 <span class="pos">+10</span> 宠爱`);
      showBedDialogue(c);
    }
  }

  function showBedDialogue(c){
    const dlg=pick(BED_DIALOGUES);
    const el=document.getElementById('bed-dialogue-content');
    let html='<div style="text-align:center;margin-bottom:16px;">';
    html+=portraitHTML(c.portraitIdx,80,100,c.princessPortrait);
    html+=`<div style="font-size:16px;font-weight:bold;color:#c49030;margin-top:8px;">${c.title?c.title+c.rank:c.name}</div>`;
    html+='</div>';
    html+='<div class="bed-dialogue">';
    html+=`<div class="bed-dialogue-line bed-dialogue-emp">${dlg.emp}</div>`;
    html+=`<div class="bed-dialogue-line bed-dialogue-con">${dlg.con}</div>`;
    const extra=[
      '<div class="bed-dialogue-line bed-dialogue-emp">皇上：时间不早了，歇息吧。</div>',
      '<div class="bed-dialogue-line bed-dialogue-con">臣妾喜欢跟着皇上。</div>',
    ];
    extra.forEach(e=>html+=e);
    html+='</div>';
    html+='<button class="btn-primary" onclick="Game.endBed()">侍寝结束</button>';
    el.innerHTML=html;
    document.getElementById('modal-bed-dialogue').classList.add('show');
  }

  function endBed(){
    const c=state.concubines.find(x=>x.id===state._bedTarget);
    if(!c){
      document.getElementById('modal-bed-dialogue').classList.remove('show');
      showFeedback('侍寝已结束');
      delete state._bedTarget;delete state._bedPool;delete state._bedFlipping;
      closeModal();
      return;
    }
    document.getElementById('modal-bed-dialogue').classList.remove('show');
    state._bedTarget=c.id;
    const el=document.getElementById('bed-rate-content');
    el.innerHTML=`<div style="text-align:center;">
      <div style="font-size:18px;color:#8a7060;margin-bottom:16px;">今夜侍寝的是 <b style="color:#c49030;">${c.name}</b></div>
      <p style="color:#8a7060;font-size:13px;margin-bottom:16px;">皇上满意吗？</p>
      <div class="bed-satisfy-btns">
        <button class="bed-satisfy-btn yes" onclick="Game.rateBed('satisfied')">&#128077; 满意</button>
        <button class="bed-satisfy-btn no" onclick="Game.rateBed('unsatisfied')">&#128078; 不满意</button>
      </div>
    </div>`;
    document.getElementById('modal-bed-rate').classList.add('show');
  }

  function rateBed(rating){
    const c=state.concubines.find(x=>x.id===state._bedTarget);
    if(!c){
      document.getElementById('modal-bed-rate').classList.remove('show');
      showFeedback('侍寝已结束');
      delete state._bedTarget;delete state._bedPool;delete state._bedFlipping;
      closeModal();
      return;
    }
    let favorChange,healthChange,msg;
    if(rating==='satisfied'){
      favorChange=rand(10,20);
      healthChange=rand(3,8);
      c.favor=clamp(c.favor+favorChange,0,2200);
      c.health=clamp(c.health+healthChange,0,100);
      c.power=clamp(c.power+3,0,500);
      if(!c.pregnant&&c.rank!=='皇后'&&Math.random()<0.25){c.pregnant=true;c.pregMonth=1;c.power=clamp(c.power+8,0,500);setTimeout(()=>showPregnancyAlert(c.name,8),500);}
      triggerFavorBackground(c);
      const rc=checkRankChange(c);
      logEvent('侍寝','皇上满意'+c.name);
      document.getElementById('modal-bed-rate').classList.remove('show');
      save();updateUI();
      msg='皇上很满意！<br>'+c.name+' 宠爱 <span class="pos">+'+favorChange+'</span>&#65292;&#21183;&#21147; <span class="pos">+3</span><br>健康 <span class="pos">+'+healthChange+'</span>';
      if(rc){msg+='<br>&#21183;&#21147;&#28287;&#36275;&#65292;<span class="pos">'+c.name+' &#26187;&#21319;&#20026; '+rc.rank+'</span>';}
      showFeedback(msg);
    } else {
      favorChange=rand(5,10);
      c.favor=clamp(c.favor-favorChange,0,2200);
      c.power=clamp(c.power-2,0,500);
      triggerFavorBackground(c);
      const rc=checkRankChange(c);
      logEvent('侍寝','皇上不满意'+c.name);
      document.getElementById('modal-bed-rate').classList.remove('show');
      save();updateUI();
      msg='皇上不太满意。。。'+c.name+' 宠爱 <span class="neg">-'+favorChange+'</span>&#65292;&#21183;&#21147; <span class="neg">-2</span>';
      if(rc){msg+='<br>&#21183;&#21147;&#19981;&#36275;&#65292;<span class="neg">'+c.name+' &#38477;&#20026; '+rc.rank+'</span>';}
      showFeedback(msg);
    }
    delete state._bedTarget;
    delete state._bedPool;
    delete state._bedFlipping;
    closeModal();
  }

