  function tryTriggerMorning(){
    if(state.morningTriggered)return;
    if(state.concubines.length===0)return;
    if(state.pendingEvent)return;
    if(state._bedTarget)return;
    if(state.eventResolvedPending)return;
    if(Math.random()>0.35)return;
    state.morningTriggered=true;
    const c=state.concubines[Math.floor(Math.random()*state.concubines.length)];
    startMorning(c);
  }

  function startMorning(c){
    tryOpenModal(()=>{
    state._morningConcubine=c.id;
    state._morningRound=1;
    state._morningFavorChange=0;
    const dlgSet=MORNING_DIALOGUES[c.personality.name]||MORNING_DIALOGUES['端庄'];
    const dlg=dlgSet[Math.floor(Math.random()*dlgSet.length)];
    state._morningDialogue=dlg;
    state._morningOptions=dlg.opts;
    renderMorningDialogue(c);
  });}

  function renderMorningDialogue(c){
    const dlg=state._morningDialogue;
    const opts=state._morningOptions;
    const el=document.getElementById('morning-content');
    let html='<div style="padding:8px;">';
    html+=`<div style="text-align:center;margin-bottom:12px;">${portraitHTML(c.portraitIdx,60,76,c.princessPortrait)}
      <div style="font-size:15px;font-weight:bold;color:#c49030;margin-top:4px;">${c.rank} ${c.name}</div>
      <div style="font-size:11px;color:#9060c0;">${c.personality.name}</div></div>`;
    if(state._morningRound===1){
      html+=`<div style="background:rgba(255,245,230,0.8);border:1px solid rgba(200,160,80,0.2);border-radius:12px;padding:12px 16px;margin-bottom:14px;font-size:14px;color:#5a3e28;line-height:1.6;">${dlg.r1c}</div>`;
    } else {
      html+=`<div style="background:rgba(255,245,230,0.8);border:1px solid rgba(200,160,80,0.2);border-radius:12px;padding:12px 16px;margin-bottom:14px;font-size:14px;color:#5a3e28;line-height:1.6;">${state._morningR2c}</div>`;
    }
    html+='<div style="display:flex;flex-direction:column;gap:6px;">';
    opts.forEach((o,i)=>{
      html+=`<button class="btn-option" onclick="Game.morningReply(${i})" style="text-align:left;padding:10px 14px;border:1px solid rgba(200,160,80,0.25);border-radius:10px;background:rgba(255,245,230,0.6);color:#5a3e28;font-size:13px;font-family:inherit;cursor:pointer;">${o.t}</button>`;
    });
    html+='</div></div>';
    el.innerHTML=html;
    document.querySelector('#modal-morning .modal-header').textContent='妃 子 请 安';
    document.getElementById('modal-morning').classList.add('show');
  }

  function morningReply(idx){
    const c=state.concubines.find(x=>x.id===state._morningConcubine);
    if(!c){
      document.getElementById('modal-morning').classList.remove('show');
      delete state._morningConcubine;delete state._morningRound;delete state._morningDialogue;
      delete state._morningOptions;delete state._morningFavorChange;delete state._morningR2c;
      closeModal();
      showFeedback('请安已结束');
      return;
    }
    const opts=state._morningOptions;
    const chosen=opts[idx];if(!chosen)return;
    state._morningFavorChange+=chosen.f;

    if(state._morningRound===1){
      state._morningRound=2;
      const r2Lines=MORNING_R2_LINES[c.personality.name]||MORNING_R2_LINES['端庄'];
      state._morningR2c=r2Lines[Math.floor(Math.random()*r2Lines.length)];
      state._morningOptions=[
        {t:'朕明白了',r:'皇上圣明。',f:3},
        {t:'你说得对',r:'谢皇上认可。',f:6},
        {t:'朕自有主张',r:'是，臣妾多嘴了。',f:-2},
      ];
      renderMorningDialogue(c);
    } else {
      const favorChange=state._morningFavorChange;
      c.favor=clamp(c.favor+favorChange,0,2200);
      const powerDelta=favorChange>0?Math.ceil(favorChange/4):Math.floor(favorChange/4);
      c.power=clamp(c.power+powerDelta,0,500);
      const rc=checkRankChange(c);
      logEvent('请安',`${c.name} 请安对话`);
      document.getElementById('modal-morning').classList.remove('show');
      delete state._morningConcubine;delete state._morningRound;delete state._morningDialogue;
      delete state._morningOptions;delete state._morningFavorChange;delete state._morningR2c;
      closeModal();
      save();updateUI();
      let msg=`${c.name} 请安完毕<br>宠爱 ${favorChange>0?'<span class="pos">+'+favorChange+'</span>':'<span class="neg">'+favorChange+'</span>'}&#65292;&#21183;&#21147; ${powerDelta>0?'<span class="pos">+'+powerDelta+'</span>':'<span class="neg">'+powerDelta+'</span>'}`;
      if(rc){msg+=`<br><span class="pos">${c.name} 晋升为 ${rc.rank}</span>`;}
      showFeedback(msg);
    }
  }

  // ===== 宴会系统 =====
  const BANQUET_PROGRAMS = {
    '舞蹈': {base:60,bonus:'talent',bonusWeight:0.4,traits:['舞蹈'],desc:'翩翩起舞，姿态优美'},
    '歌唱': {base:55,bonus:'talent',bonusWeight:0.35,traits:['音律','古筝','琵琶','笛箫','古琴'],desc:'歌声婉转，余音绕梁'},
    '诗词': {base:50,bonus:'wisdom',bonusWeight:0.4,traits:['诗词歌赋'],desc:'吟诗作对，才情出众'},
    '琴艺': {base:58,bonus:'talent',bonusWeight:0.35,traits:['音律','古琴','古筝'],desc:'琴声悠扬，引人入胜'},
    '棋艺': {base:45,bonus:'wisdom',bonusWeight:0.45,traits:['围棋','棋艺'],desc:'以棋会友，布局精妙'},
    '书画': {base:52,bonus:'talent',bonusWeight:0.35,traits:['书法','绘画','琴棋书画'],desc:'挥毫泼墨，笔走龙蛇'},
    '茶艺': {base:60,bonus:'wisdom',bonusWeight:0.3,traits:['茶道'],desc:'烹茶品茗，雅致从容'},
    '女红': {base:55,bonus:'talent',bonusWeight:0.35,traits:['女红','刺绣'],desc:'针线功夫，匠心独运'},
    '花艺': {base:60,bonus:'talent',bonusWeight:0.3,traits:['插花','琴棋书画'],desc:'插花弄草，赏心悦目'},
    '香道': {base:55,bonus:'wisdom',bonusWeight:0.35,traits:['香道'],desc:'焚香品韵，宁静致远'},
  };

  function openBanquet(){
    if(state.concubines.length===0){showFeedback('后宫空无一人，无法举办宴会！');return;}
    if(state.pendingEvent){showFeedback('请先处理后宫异动事件！');return;}
    if(state.banquetHeld){showFeedback('本月已举办过宴会了！');return;}
    if(state.treasury<800){showFeedback('国库不足800两，无法举办宴会！');return;}
    if(state.actionsLeft<=0){showFeedback('本月行动已用完！');return;}
    state._banquetSelected=null;
    let html='<div style="text-align:center;padding:4px 0;">';
    html+='<p style="color:#a08060;font-size:13px;margin-bottom:12px;">选择宴会表演内容</p>';
    html+='<div style="display:grid;grid-template-columns:repeat(2,1fr);gap:8px;margin-bottom:16px;" id="banquet-prog-list">';
    Object.keys(BANQUET_PROGRAMS).forEach((prog,idx)=>{
      const p=BANQUET_PROGRAMS[prog];
      html+=`<button class="btn-banquet" id="banquet-prog-${idx}" onclick="Game.selectBanquetProg('${prog}',${idx})" style="opacity:0.6;border-color:rgba(200,120,60,0.2);">${prog}<br><span style="font-size:11px;opacity:0.7;">${p.desc}</span></button>`;
    });
    html+='</div></div>';
    html+='<button class="btn-primary" style="margin:0;opacity:0.5;" id="banquet-submit-btn" onclick="Game.submitBanquet()" disabled>提 交</button>';
    document.getElementById('banquet-content').innerHTML=html;
    tryOpenModal(()=>{document.getElementById('modal-banquet').classList.add('show');});
  }

  function selectBanquetProg(prog,idx){
    state._banquetSelected=prog;
    // Highlight selected
    Object.keys(BANQUET_PROGRAMS).forEach((p,i)=>{
      const el=document.getElementById('banquet-prog-'+i);
      if(!el)return;
      if(i===idx){
        el.style.opacity='1';
        el.style.borderColor='rgba(200,120,60,0.6)';
        el.style.background='linear-gradient(180deg,rgba(200,120,60,0.35),rgba(180,100,40,0.35))';
      } else {
        el.style.opacity='0.6';
        el.style.borderColor='rgba(200,120,60,0.2)';
        el.style.background='linear-gradient(180deg,rgba(200,120,60,0.25),rgba(180,100,40,0.25))';
      }
    });
    const btn=document.getElementById('banquet-submit-btn');
    if(btn){btn.disabled=false;btn.style.opacity='1';}
  }

  function submitBanquet(){
    const prog=state._banquetSelected;
    if(!prog)return;
    if(state.treasury<800){showFeedback('国库不足800两！');return;}
    state.treasury-=800;
    state.actionsLeft--;
    // Each concubine performs
    const results=state.concubines.map(c=>{
      const score=calcBanquetScore(c,prog);
      const p=BANQUET_PROGRAMS[prog];
      let traitMatch=false;
      p.traits.forEach(t=>{if(c.trait&&c.trait.indexOf(t)>=0)traitMatch=true;});
      return {concubine:c,score,prog,traitMatch};
    });
    results.sort((a,b)=>b.score-a.score);
    const champion=results[0];
    state.banquetHeld=true;
    champion.concubine.favor=clamp(champion.concubine.favor+30,0,2200);
    logEvent('宴会',`${champion.concubine.name}表演${champion.prog}，得分${champion.score}，获魁`);
    save();updateUI();
    // Show results
    let html='<div style="text-align:center;padding:8px;">';
    html+=`<div style="font-size:18px;color:#c49030;margin-bottom:4px;">&#127881; 宴会结束</div>`;
    html+=`<div style="font-size:12px;color:#8a7060;margin-bottom:12px;">表演内容：${prog} | 国库 -800两</div>`;
    html+='<div style="max-height:55vh;overflow-y:auto;margin-bottom:12px;">';
    results.forEach((r,i)=>{
      const isChampion=i===0;
      const medal=i===0?'&#127942;':i===1?'&#129352;':i===2?'&#129353;':`<span style="color:#b0a090;font-size:13px;">#${i+1}</span>`;
      const bg=isChampion?'rgba(200,160,80,0.15)':'rgba(255,245,230,0.4)';
      const borderColor=isChampion?'rgba(200,160,80,0.4)':'rgba(200,160,80,0.1)';
      const promoteNote='';
      const favorNote=isChampion?`<span style="color:#c49030;font-size:11px;"> +30宠爱</span>`:'';
      const traitNote=r.traitMatch?'<span style="color:#e89060;font-size:10px;"> 擅长</span>':'';
      const scoreColor=isChampion?'#c49030':r.score>=80?'#4a9a5a':r.score>=60?'#8a7060':'#b0a090';
      html+=`<div style="display:flex;align-items:center;padding:10px 12px;margin:4px 0;border-radius:10px;background:${bg};border:1px solid ${borderColor};">
        <div style="font-size:18px;min-width:36px;text-align:center;">${medal}</div>
        <div style="flex:1;text-align:left;padding:0 8px;">
          <div style="font-size:14px;font-weight:bold;color:${isChampion?'#c49030':'#5a3e28'};">${r.concubine.name}${traitNote}</div>
          <div style="font-size:11px;color:#8a7060;">${r.prog} | 得分 <b style="color:${scoreColor}">${r.score}</b>${favorNote}${promoteNote}</div>
        </div>
        <div style="font-size:20px;">${portraitHTML(r.concubine.portraitIdx,30,38,r.concubine.princessPortrait)}</div>
      </div>`;
    });
    html+='</div></div>';
    html+='<button class="btn-primary" style="margin:0;" onclick="Game.confirmBanquet()">确 认</button>';
    document.getElementById('banquet-content').innerHTML=html;
    // Trigger palace event if not yet triggered this month
    const used=5-state.actionsLeft;
    if(state.concubines.length>=2&&!state.pendingEvent&&!state.eventTriggeredThisMonth){
      triggerPalaceEvent();
      state.eventTriggeredThisMonth=true;
    }
  }

  function calcBanquetScore(c, prog){
    const p=BANQUET_PROGRAMS[prog];
    let score=p.base;
    const bonusVal=p.bonus==='talent'?c.talent:c.wisdom;
    score+=bonusVal*p.bonusWeight;
    let traitMatch=false;
    p.traits.forEach(t=>{
      if(c.trait&&c.trait.indexOf(t)>=0)traitMatch=true;
    });
    if(traitMatch)score+=15;
    score+=rand(-5,5);
    return Math.round(Math.max(20,score));
  }

  function confirmBanquet(){
    document.getElementById('modal-banquet').classList.remove('show');
  }

