  function _punish(idx){
    console.log('_punish called with idx:', idx, 'puns:', state._puns);
    const p=state._puns;
    if(!p){console.log('_punish: no puns data');return;}
    const perp=state.concubines.find(c=>c.id===p.perpId);
    const victim=p.victimId?state.concubines.find(c=>c.id===p.victimId):null;
    const perpName=p.perpName;
    const victimName=p.victimName;
    const eventTitle=p.eventTitle;
    state._puns=null;
    state.pendingEvent=null;
    state._punishmentShown=false;
    state._selectedPunish=null;
    var btn=document.getElementById('event-confirm-btn');
    if(btn){btn.textContent='确认';btn.onclick=function(){Game.confirmEventOption();};}
    // Force hide the event modal immediately
    const eventModal=document.getElementById('modal-event');
    eventModal.classList.remove('show');
    eventModal.style.display='none';
    if(!perp){closeModal();setTimeout(()=>{eventModal.style.display='';},100);save();updateUI();return;}
    if(idx===0){
      logBehavior(perp,p.eventType||'unknown','heavy',true);
      updateStress(perp,30);
      state._executeVictimInfo={victimId:p.victimId,victimName:victimName};
      showExecutionSelect(perp.id,false,false,{eventType:p.eventType||'',vars:{perpName:perpName,victimName:victimName||'',year:state.year,month:state.month}});
      return;
    } else if(idx===1){
      logBehavior(perp,p.eventType||'unknown','heavy',true);
      updateStress(perp,30);
      if(victim){updateStress(victim,-15);}
      state.concubines=state.concubines.filter(x=>x.id!==perp.id);
      perp.health=clamp(perp.health-20,0,100);
      state.coldPalaceList.push(perp);
      logEvent(eventTitle,'打入冷宫'+perpName);
      if(victim){victim.favor=clamp(victim.favor+10,0,2200);victim.health=clamp(victim.health+5,0,100);}
      closeModal();save();updateUI();
      showFeedback(`${perpName} 被打入冷宫<br>${victimName} 宠爱 <span class="pos">+10</span>，健康 <span class="pos">+5</span>`);
    } else if(idx===2){
      logBehavior(perp,p.eventType||'unknown','medium',true);
      updateStress(perp,20);
      if(victim){updateStress(victim,-10);}
      perp.health=clamp(perp.health-30,0,100);
      perp.favor=clamp(perp.favor-20,0,2200);
      perp.power=clamp(perp.power-15,0,500);
      logEvent(eventTitle,'杖刑'+perpName);
      if(victim){victim.favor=clamp(victim.favor+5,0,2200);victim.health=clamp(victim.health+5,0,100);}
      closeModal();save();updateUI();
      showFeedback(`${perpName} 受杖刑<br>健康 <span class="neg">-30</span>，宠爱 <span class="neg">-20</span>&#65292;&#21183;&#21147; <span class="neg">-15</span><br>${victimName} 宠爱 <span class="pos">+5</span>，健康 <span class="pos">+5</span>`);
    } else if(idx===3){
      logBehavior(perp,p.eventType||'unknown','light',true);
      updateStress(perp,10);
      if(victim){updateStress(victim,-5);}
      perp.favor=clamp(perp.favor-10,0,2200);
      state.banned[perp.id]=3;
      logEvent(eventTitle,'禁足'+perpName);
      if(victim){victim.favor=clamp(victim.favor+5,0,2200);}
      closeModal();save();updateUI();
      showFeedback(`${perpName} 禁足 3月<br>宠爱 <span class="neg">-10</span><br>${victimName} 宠爱 <span class="pos">+5</span>`);
    } else if(idx===4){
      logBehavior(perp,p.eventType||'unknown','medium',true);
      updateStress(perp,20);
      if(victim){updateStress(victim,-8);}
      if(perp&&perp.rank!=='官女子'){
        let newR=perp.rank;
        const rd2=rd(newR);
        if(rd2&&rd2!==newR)newR=rd2;
        perp.rank=newR;
      }
      perp.power=clamp(perp.power-30,0,500);
      perp.favor=clamp(perp.favor-15,0,2200);
      const rc=checkRankChange(perp);
      logEvent(eventTitle,'降低位份'+perpName);
      if(victim){victim.favor=clamp(victim.favor+5,0,2200);victim.power=clamp(victim.power+5,0,500);}
      closeModal();save();updateUI();
      let msg=`${perpName} 位份降为 <span class="neg">${perp.rank}</span><br>势力 <span class="neg">-30</span>，宠爱 <span class="neg">-15</span>`;
      if(rc&&rc.type==='demote')msg+=`<br>因势力不足，进一步降为 <span class="neg">${rc.rank}</span>`;
      msg+=`<br>${victimName} 宠爱 <span class="pos">+5</span>&#65292;&#21183;&#21147; <span class="pos">+5</span>`;
      showFeedback(msg);
    }
    // 更新关系网
    if(perp&&victim){
      if(!perp.favors)perp.favors={};
      if(!victim.favors)victim.favors={};
      perp.favors[victim.id]=(perp.favors[victim.id]||0)-15;
      victim.favors[perp.id]=(victim.favors[perp.id]||0)-30;
    }
    setTimeout(()=>{eventModal.style.display='';},100);
  }


  function _dismissEvent(){
    state.pendingEvent=null;
    state._selectedEventOption=null;
    state._punishmentShown=false;
    state._puns=null;
    state._selectedPunish=null;
    const em=document.getElementById('modal-event');
    em.classList.remove('show');
    em.style.display='none';
    closeModal();
    var btn=document.getElementById('event-confirm-btn');
    if(btn){btn.textContent='确认';btn.onclick=function(){Game.confirmEventOption();};}
    setTimeout(()=>{em.style.display='';},100);
    save();updateUI();
  }

