  // ===== 事件生成 =====
  function generateEvent(){
    const con=[...state.concubines].sort(()=>Math.random()-0.5);
    if(con.length<2){
      if(con.length===0)return null;
      return genSingle(con[0]);
    }
    // ===== 第一优先级：危急病故事件（优先于其他事件）=====
    // health <= 0 的妃子 100% 触发
    const zeroHealth=con.filter(c=>c.health<=0);
    if(zeroHealth.length>0){
      const c=zeroHealth.reduce((a,b)=>a.health<b.health?a:b);
      executeIllnessDeath(c);
      return state.pendingEvent;
    }
    // ===== 第二优先级：正常事件池 =====
    const r=Math.random();
    if(r<0.05){const ce=genColdPalacePlea();if(ce)return ce;}
    if(r<0.10){const pe=genPregnancyEvent();if(pe)return pe;}
    if(r<0.25){const ie=genIllnessDeath(con);if(ie)return ie;}
    if(r<0.23){const cr=genChildRivalry(con);if(cr)return cr;}
    if(r<0.26){const ci=genColdPalaceIllness(con);if(ci)return ci;}
    if(r<0.40){const pe=genPoisoning(con);if(pe)return pe;}
    if(r<0.52){const he=genHarmHeir(con);if(he)return he;}
    if(r<0.60){const hce=genHarmChild(con);if(hce)return hce;}
    if(r<0.62){const ae=genAdultery(con);if(ae)return ae;}
    if(r<0.71){const ee=genEmbezzle(con);if(ee)return ee;}
    if(r<0.72){const fe=genFamilyCrime(con);if(fe)return fe;}
    if(r<0.79)return genJealousy(con);
    if(r<0.85)return genFramed(con);
    if(r<0.92)return genRumor(con);
    // 争宠博弈类
    if(r<0.94){const pe2=genPerformance(con);if(pe2)return pe2;}
    if(r<0.95){const sc=genScheme(con);if(sc)return sc;}
    return genFlatter(con);
  }

  // ===== 事件处理 =====
  function showEventModal(){
    if(!state.pendingEvent)return;
    state._selectedEventOption=null;
    state._punishmentShown=false;
    state._puns=null;
    state._selectedPunish=null;
    const ev=state.pendingEvent;
    const el=document.getElementById('event-content');
    let html=`<div class="event-title">${ev.title}</div>`;
    html+=`<div class="event-desc">${ev.desc}</div>`;
    ev.options.forEach((opt,i)=>{
      html+=`<button class="event-option" id="event-opt-${i}" onclick="Game.selectEventOption(${i})">${opt.text}</button>`;
    });
    el.innerHTML=html;
    const btn=document.getElementById('event-confirm-btn');
    if(btn){btn.textContent='确认';btn.disabled=true;btn.style.opacity='0.5';btn.onclick=function(){Game.confirmEventOption();};}
    tryOpenModal(()=>{document.getElementById('modal-event').classList.add('show');});
  }

  function selectEventOption(idx){
    if(!state.pendingEvent)return;
    state._selectedEventOption=idx;
    const ev=state.pendingEvent;
    ev.options.forEach((_,i)=>{
      const optEl=document.getElementById('event-opt-'+i);
      if(optEl){
        if(i===idx){
          optEl.style.borderColor='rgba(200,160,80,0.6)';
          optEl.style.background='rgba(240,220,200,0.9)';
        } else {
          optEl.style.borderColor='rgba(200,160,80,0.25)';
          optEl.style.background='rgba(255,245,230,0.7)';
        }
      }
    });
    const btn=document.getElementById('event-confirm-btn');
    if(btn){btn.disabled=false;btn.style.opacity='1';}
  }

  function confirmEventOption(){
    if(state._selectedEventOption===null||!state.pendingEvent)return;
    const idx=state._selectedEventOption;
    const ev=state.pendingEvent;
    if(idx>=0&&idx<ev.options.length){ev.options[idx].effect();}
    if(state._punishmentShown){state._punishmentShown=false;return;}
    state.pendingEvent=null;
    state._selectedEventOption=null;
    closeModal();
    document.getElementById('modal-event').classList.remove('show');
    var btn=document.getElementById('event-confirm-btn');
    if(btn){btn.textContent='确认';btn.onclick=function(){Game.confirmEventOption();};}
    save();updateUI();
  }

  function handleEventOption(idx){
    selectEventOption(idx);
  }

  function openPendingEvent(){
    if(state.pendingEvent){showEventModal();}
    else{showFeedback('当前没有待处理事件。');}
  }

  function logEvent(type,detail){
    state.eventLog.unshift({type,detail,month:state.month,year:state.year});
    if(state.eventLog.length>100) state.eventLog.pop();
  }

  // ===== 履历衰减因子 =====
  function historyFactor(concubine, eventType){
    if(!concubine||!concubine.behaviorLog||!eventType)return 1.0;
    let factor=1.0;
    for(const log of concubine.behaviorLog){
      if(log.eventType===eventType&&log.punished){
        const monthsAgo=(state.year-log.year)*12+(state.month-log.month);
        if(log.severity==='heavy')factor*=0.25;
        else if(log.severity==='medium')factor*=0.5;
        else factor*=0.75;
        const recovery=Math.min(0.8,0.1*Math.floor(monthsAgo/6));
        factor+=recovery;
      }
    }
    return Math.min(factor,1.0);
  }

  // ===== 加权选人 =====
  function pickWeighted(list, eventType, role){
    if(!list||list.length===0)return null;
    const weights=PERSONALITY_EVENT_WEIGHTS[eventType];
    if(!weights)return pick(list);
    let total=0;
    const scored=list.map(c=>{
      const pname=c.personality?c.personality.name:'';
      let w=weights[pname]||weights['default']||1.0;
      w*=historyFactor(c, eventType);
      if(c.stress!==undefined){w*=(1+c.stress/100);}
      total+=w;
      return{concubine:c,weight:w};
    });
    if(total<=0)return pick(list);
    let r=Math.random()*total;
    for(const s of scored){r-=s.weight;if(r<=0)return s.concubine;}
    return scored[scored.length-1].concubine;
  }

  // ===== 记录行为履历 =====
  function logBehavior(concubine, eventType, severity, punished){
    if(!concubine)return;
    if(!concubine.behaviorLog)concubine.behaviorLog=[];
    concubine.behaviorLog.push({eventType,year:state.year,month:state.month,severity,punished:!!punished});
    if(concubine.behaviorLog.length>50)concubine.behaviorLog.splice(0,20);
  }

  // ===== 更新压力值 =====
  function updateStress(concubine, delta){
    if(!concubine)return;
    if(concubine.stress===undefined)concubine.stress=0;
    concubine.stress=clamp(concubine.stress+delta,0,100);
  }

  // ===== 检查压力爆发 =====
  function checkStressBreakdown(){
    const candidates=state.concubines.filter(c=>{
      const cap=c.stressCap||getStressCap(c.personality?c.personality.name:'');
      return c.stress>=cap;
    });
    if(candidates.length===0)return null;
    const c=pick(candidates);
    const r=Math.random();
    let outcome=null;
    if(r<0.30){outcome={title:'【失仪御前】',desc:`${c.rank}${c.name}近日心神不宁，今日在御前失仪，言语颠倒，举止失常。众妃皆惊。`,type:'breakdown_mad'};}
    else if(r<0.55){outcome={title:'【暗生歹念】',desc:`${c.rank}${c.name}近来性情大变，暗中筹划着什么。宫女说她夜半独坐，喃喃自语。`,type:'breakdown_harm'};}
    else if(r<0.75){outcome={title:'【忧思成疾】',desc:`${c.rank}${c.name}忧思过度，郁郁寡欢，终至成疾。太医说乃心病，需得宽慰。`,type:'breakdown_ill'};}
    else if(r<0.90){outcome={title:'【夜半出逃】',desc:`太监来报，${c.rank}${c.name}夜半收拾细软，欲逃出宫去。已被侍卫拦下。`,type:'breakdown_flee'};}
    else{outcome={title:'【崩溃大哭】',desc:`${c.rank}${c.name}突然崩溃大哭，声泪俱下，说活着太苦了。宫人皆不敢言。`,type:'breakdown_cry'};}
    return{...outcome,options:[
      {text:' 安抚宽慰（宠爱+30，压力-30）',effect(){c.favor=clamp(c.favor+30,0,2200);updateStress(c,-30);logEvent('压力爆发','安抚'+c.name);save();updateUI();showFeedback(`安抚 <span class="pos">${c.name}</span><br>宠爱 <span class="pos">+30</span>，压力 <span class="pos">-30</span>`);}},
      {text:' 禁足静养（压力-20，宠爱-10）',effect(){c.favor=clamp(c.favor-10,0,2200);updateStress(c,-20);state.banned[c.id]=2;logEvent('压力爆发','禁足'+c.name);save();updateUI();showFeedback(`${c.name} 禁足静养<br>宠爱 <span class="neg">-10</span>`);}},
      {text:' 不予理会（压力-5）',effect(){updateStress(c,-5);logEvent('压力爆发','不理'+c.name);save();updateUI();showFeedback(`${c.name} 无人问津`);}},
    ]};
  }

  function triggerPalaceEvent(){
    if(state.concubines.length<2)return;
    if(state.pendingEvent)return;
    if(state.eventTriggerRate<=0)return;
    if(document.getElementById('modal-draft').classList.contains('show')||state._drafting)return;
    const ev=generateEvent();
    if(ev){state.pendingEvent=ev;save();updateUI();setTimeout(()=>showEventModal(),500);}
  }

  // ===== 选秀系统 =====
  function triggerDraft(){
    if(state.concubines.length>30){showFeedback('后宫已满30人，无法选秀！');return;}
    state._drafting=true;
    state._draftPool=[];
    state._draftSelected=[];
    state._draftIdx=0;
    for(let i=0;i<3;i++){
      state._draftPool.push(genConcubine(true));
    }
    showDraftCandidate();
  }

  // ===== 选秀语音 =====
  function playDraftVoice(c){
    try{
      window.speechSynthesis.cancel();
      const u=new SpeechSynthesisUtterance('民女参见皇上');
      u.lang='zh-CN';
      // 根据秀女ID生成固定随机种子，保证同一秀女音色一致
      let seed=0;
      for(let i=0;i<c.id.length;i++) seed=(seed*31+c.id.charCodeAt(i))&0x7fffffff;
      const pseudoRand=function(){seed=(seed*16807)%2147483647;return seed/2147483647;};
      // 音调1.0~1.8，语速0.7~1.1，模拟不同年龄/性格的声音
      u.pitch=1.0+pseudoRand()*0.8;
      u.rate=0.7+pseudoRand()*0.4;
      const voices=window.speechSynthesis.getVoices();
      const zhVoice=voices.find(v=>v.lang.startsWith('zh')&&/female|女|ting|xiaoxiao|huihui/i.test(v.name))
        ||voices.find(v=>v.lang.startsWith('zh'))
        ||voices.find(v=>v.lang.startsWith('zh-CN'));
      if(zhVoice)u.voice=zhVoice;
      window.speechSynthesis.speak(u);
    }catch(e){}
  }

  function showDraftCandidate(){
    if(state._draftIdx>=state._draftPool.length){
      finishDraft();
      return;
    }
    const c=state._draftPool[state._draftIdx];
    const hpColor=c.health>=70?'#4caf50':c.health>=40?'#ff9800':'#e55555';
    // 播放选秀语音
    playDraftVoice(c);
    const el=document.getElementById('draft-content');
    let html='<div style="text-align:center;padding:16px 16px 12px;">';
    // 大头像
    html+=portraitHTML(c.portraitIdx,160,200);
    html+=`<div style="font-size:20px;font-weight:bold;color:#c49030;margin-top:10px;">${c.name}</div>`;
    html+=`<div style="font-size:12px;color:#a08060;margin-top:2px;">${c.age}岁 · ${c.family.name} · 推荐位份 <b style="color:#c49030;">${c.family.initRank}</b></div>`;
    html+='</div>';
    // 属性面板
    html+='<div style="padding:0 16px 12px;">';
    html+='<div style="background:rgba(255,245,230,0.8);border:1px solid rgba(200,160,80,0.2);border-radius:10px;padding:12px 14px;">';
    html+='<div style="display:flex;flex-wrap:wrap;gap:8px 16px;font-size:13px;color:#5a3e28;line-height:1.8;">';
    html+=`<div style="flex:1;min-width:100px;">美貌 <b style="color:#e06080;">${c.beauty}</b></div>`;
    html+=`<div style="flex:1;min-width:100px;">才华 <b style="color:#6080e0;">${c.talent}</b></div>`;
    html+=`<div style="flex:1;min-width:100px;">智慧 <b style="color:#40a080;">${c.wisdom}</b></div>`;
    html+=`<div style="flex:1;min-width:100px;">健康 <b style="color:${hpColor};">${c.health}</b></div>`;
    html+=`<div style="flex:1;min-width:100px;">性格 <b style="color:#9060c0;">${c.personality.name}</b></div>`;
    html+=`<div style="flex:1;min-width:100px;">特长 <b style="color:#c49030;">${c.trait}</b></div>`;
    html+='</div></div></div>';
    // 进度提示
    html+=`<div style="text-align:center;font-size:11px;color:#a08060;margin-bottom:8px;">第 ${state._draftIdx+1}/${state._draftPool.length} 位</div>`;
    // 按钮
    html+='<div style="display:flex;gap:12px;padding:0 16px 16px;">';
    html+='<button class="draft-btn-keep" onclick="Game.draftKeep()">留 牌 子</button>';
    html+='<button class="draft-btn-drop" onclick="Game.draftDrop()">撂 牌 子</button>';
    html+='</div>';
    el.innerHTML=html;
    document.querySelector('#draft-modal-header').textContent='秀 女 入 选';
    tryOpenModal(()=>{document.getElementById('modal-draft').classList.add('show');});
  }

  function draftKeep(){
    const c=state._draftPool[state._draftIdx];
    state._draftSelected.push(c);
    state._draftIdx++;
    closeModal();
    setTimeout(()=>showDraftCandidate(),300);
  }

  function draftDrop(){
    state._draftIdx++;
    closeModal();
    setTimeout(()=>showDraftCandidate(),300);
  }

  function finishDraft(){
    document.getElementById('modal-draft').classList.remove('show');
    if(state._draftSelected.length>0){
      const names=[];
      var totalDowry = 0;
      state._draftSelected.forEach(c=>{
        // 选秀陪嫁：母家带来一次性收入
        var dowry = 0;
        if(c.family && c.family.name !== '平民秀女'){
          var fn = c.family.name;
          if(fn.indexOf('国公')>=0 || fn.indexOf('宗室')>=0) dowry = rand(300,600);
          else if(fn.indexOf('一品')>=0 || fn.indexOf('侯爵')>=0) dowry = rand(200,500);
          else if(fn.indexOf('二品')>=0 || fn.indexOf('伯爵')>=0) dowry = rand(100,300);
          else if(fn.indexOf('三品')>=0) dowry = rand(60,150);
          else if(fn.indexOf('四品')>=0) dowry = rand(40,100);
          else if(fn.indexOf('五品')>=0) dowry = rand(20,60);
        }
        if(dowry > 0) totalDowry += dowry;
        state.concubines.push(c);
        names.push(c.name);
        logEvent('选秀',`${c.name} 入宫`);
      });
      if(totalDowry > 0){
        state.treasury += totalDowry;
        save();updateUI();
        showFeedback(`<span class="pos">${names.join('、')}</span> 已选入后宫<br>📦 母家陪嫁 <span class="pos">+${totalDowry}</span> 两`);
      } else {
        save();updateUI();
        showFeedback(`<span class="pos">${names.join('、')}</span> 已选入后宫`);
      }
    } else {
      logEvent('选秀','全部落选');
      save();updateUI();
      showFeedback('本次选秀全部落选');
    }
    state._draftPool=[];
    state._draftSelected=[];
    state._draftIdx=0;
    state._drafting=false;
    closeModal();
  }

