  function getFavorLevel(favor){
    var level=HL_FAVOR_LEVELS[0];
    for(var i=HL_FAVOR_LEVELS.length-1;i>=0;i--){if(favor>=HL_FAVOR_LEVELS[i].min){level=HL_FAVOR_LEVELS[i];break;}}
    return level;
  }
  function getFavorKey(favor){return getFavorLevel(favor).key;}
  function getFavorName(favor){return getFavorLevel(favor).name;}
  function getFavorColor(favor){return getFavorLevel(favor).color;}
  function genHonglouBeauty(isQueen,isReunion,oldData){
    if(isReunion&&oldData){
      var od=oldData;
      var b={id:od.id,name:od.name,type:od.type,typeName:od.typeName,age:od.age||rand(17,25),beauty:od.beauty||rand(60,90),talent:od.talent||rand(40,80),wisdom:od.wisdom||rand(30,70),health:od.health||rand(75,100),personality:od.personality,trait:od.trait,price:od.price,portraitIdx:od.portraitIdx,portraitSeed:od.portraitSeed,favor:od.favor||0,favorLevel:getFavorKey(od.favor||0),visitCount:od.visitCount||0,isFlowerQueen:od.isFlowerQueen||false,isReunion:true,isQueen:false,greeting:od.greeting||pick(HL_GREETINGS)};
      // 重逢加成
      if(od.visitsSinceLastSeen>=3){b.favor=Math.min((b.favor||0)+10,100);b.price=Math.round(b.price*0.8);}
      return b;
    }
    var type=pick(HL_TYPES);
    var surname=pick(HL_SURNAMES);
    var name=pick(HL_NAMES);
    var age=rand(15,22);
    var visitBonus=Math.min((state.honglouTotalVisits||0)*0.5,5);
    var beauty=clamp(rand(type.beautyR[0],type.beautyR[1])+Math.round(visitBonus),30,99);
    var talent=clamp(rand(type.talentR[0],type.talentR[1])+Math.round(visitBonus),30,99);
    var wisdom=clamp(rand(type.wisdomR[0],type.wisdomR[1])+Math.round(visitBonus),30,99);
    if(isQueen){beauty=clamp(beauty+10,30,99);talent=clamp(talent+10,30,99);wisdom=clamp(wisdom+10,30,99);}
    var pName=pick(type.pNames);
    var personalityObj=PERSONALITIES.find(function(p){return p.name===pName;})||PERSONALITIES[0];
    var trait=pick(type.traits);
    var avgS=(beauty+talent+wisdom)/3;
    var basePrice=rand(type.priceR[0],type.priceR[1]);
    var price=Math.round(basePrice*(avgS/70));
    if(isQueen)price=Math.round(price*1.5);
    price=clamp(price,200,2000);
    var portraitIdx=pickZhPortrait();
    var portraitSeed=Math.random().toString(36).slice(2)+name;
    var greeting=pick(HL_GREETINGS).replace('{name}',name);
    var favorLevel='stranger';
    return{id:'hl_'+surname+name+'_'+Date.now().toString(36),name:surname+name,type:type.id,typeName:type.name,age:age,beauty:beauty,talent:talent,wisdom:wisdom,health:rand(75,100),personality:personalityObj,trait:trait,typeData:type,price:price,portraitIdx:portraitIdx,portraitSeed:portraitSeed,favor:0,favorLevel:favorLevel,visitCount:0,isFlowerQueen:isQueen,isReunion:false,contestScore:0,greeting:greeting};
  }
