  function updateHonglouAdoptTotal(){
    var checks=document.querySelectorAll('.hl-adopt-check:checked');
    var total=0;
    checks.forEach(function(c){total+=parseInt(c.getAttribute('data-price'));});
    document.getElementById('hl-adopt-total').textContent='共 '+checks.length+' 人，总计 '+total+' 两';
  }
  function confirmHonglouAdopt(){
    var checks=document.querySelectorAll('.hl-adopt-check:checked');
    if(checks.length===0){showFeedback('请选择要纳妾的女子。');return;}
    var hl=state._honglou;
    var totalPrice=0;
    var selected=[];
    checks.forEach(function(c){
      var idx=parseInt(c.getAttribute('data-idx'));
      var b=hl.beauties.filter(function(x){return x.favor>=40;})[idx];
      if(b){totalPrice+=parseInt(c.getAttribute('data-price'));selected.push(b);}
    });
    if(state.treasury<totalPrice){showFeedback('银两不足，需要 '+totalPrice+' 两！');return;}
    var remain=30-state.concubines.length;
    if(selected.length>remain){showFeedback('后宫只剩 '+remain+' 个名额，最多只能选 '+remain+' 人！');return;}
    state.treasury-=totalPrice;
    var names=[];
    selected.forEach(function(b){
      var disc=calcPriceDiscount(b);
      var finalPrice=Math.round(b.price*disc);
      var initRank='官女子';
      var initPower=rand(3,8);
      var concubine={id:genId(),name:b.name,age:b.age,beauty:b.beauty,talent:b.talent,wisdom:b.wisdom,health:b.health,favor:Math.round(b.beauty*1.5),power:initPower,rank:initRank,personality:b.personality,trait:b.trait,family:{name:'醉红楼',initRank:initRank,color:'#c49030'},pregnant:false,pregMonth:0,portraitIdx:b.portraitIdx,title:'',fromHonglou:true,honglouSkill:b.type,portraitSeed:b.portraitSeed,stress:0,stressCap:getStressCap(b.personality.name),behaviorLog:[],_favored:false,favors:{},grudge:null,_flatterCount:0};
      state.concubines.push(concubine);
      names.push(b.name);
      logEvent('醉红楼',b.name+' 赎身入宫，封为 '+initRank);
      // 从beauties移除
      hl.beauties=hl.beauties.filter(function(x){return x.id!==b.id;});
      if(hl.oldFlames)hl.oldFlames=hl.oldFlames.filter(function(x){return x.id!==b.id;});
    });
    save();updateUI();
    document.getElementById('modal-honglou-adopt').classList.remove('show');
    closeModal();
    showFeedback('<span class="pos">'+names.join('、')+'</span> 已赎身入宫<br>国库 <span class="neg">-'+totalPrice+'</span> 两');
    renderHonglouMain();
    document.getElementById('honglou-treasury-info').textContent='国库：'+state.treasury+' 两';
  }
