      html+='<div style="font-size:20px;font-weight:bold;color:#ffd700;margin-top:8px;">'+winner.name+'</div>';
      html+='<div style="font-size:12px;color:#b09060;">'+winner.typeName+' · '+winner.trait+'</div>';
      html+='</div>';
      html+='<div class="hl-reunion-scene">红绸高挂，金钗加顶。'+winner.name+'跪受花魁金匾，台下掌声如雷。她望向你，眼中似有泪光。</div>';
      html+='<div class="hl-perf-actions">';
