  // 离开醉红楼
  function finishHonglou(){
    var hl=state._honglou;
    if(!hl||!hl.active)return;
    // 保存旧识
    if(!state.honglouOldFlames)state.honglouOldFlames=[];
    hl.beauties.forEach(function(b){
      if(b.visitCount>0){
        var keepRate=b.favorLevel==='obsessed'?1.0:b.favorLevel==='love'?0.8:0.4;
        if(Math.random()<keepRate){
          state.honglouOldFlames.push({id:b.id,name:b.name,type:b.type,portraitIdx:b.portraitIdx,portraitSeed:b.portraitSeed,favor:b.favor,visitCount:b.visitCount,personality:{name:b.personality.name},trait:b.trait,price:b.price,typeName:b.typeName,isFlowerQueen:b.isFlowerQueen,lastVisitVisits:state.honglouTotalVisits||0,age:b.age,beauty:b.beauty,talent:b.talent,wisdom:b.wisdom,health:b.health,greeting:b.greeting});
        }
      }
    });
    // 记录访问信息
    state.honglouTotalVisits=(state.honglouTotalVisits||0)+1;
    state.honglouLastVisitMonth=state.year*12+state.month;
    state.honglouLastVisitYear=state.year;
    // 花魁大赛冷却
    state.honglouContestCooldown=(state.honglouContestCooldown||0)+1;
    // 风险判定
    triggerHonglouRisk();
    // 清理
    state._honglou.active=false;
    state._honglou=null;
    // 关闭页面
    document.getElementById('page-honglou').classList.remove('active');
    save();
  }
  // 风险判定
  function triggerHonglouRisk(){
    if(Math.random()>=0.3)return;
    var hasQueen=state.concubines.some(function(c){return c.rank==='皇后';});
    if(hasQueen&&Math.random()<0.5){
      showHonglouEvent('皇后得知',[
        {text:'去坤宁宫安抚（200两）',effect:function(){
          var q=state.concubines.find(function(c){return c.rank==='皇后';});
          if(q){q.favor=clamp(q.favor-10,0,2200);if(state.treasury>=200)state.treasury-=200;}
          showFeedback('皇上亲自去坤宁宫安抚皇后。<br>皇后宠爱 <span class="neg">-10</span>，国库 <span class="neg">-200</span>');
        }},
        {text:'不去管她',effect:function(){
          var q=state.concubines.find(function(c){return c.rank==='皇后';});
          if(q)q.favor=clamp(q.favor-20,0,2200);
          showFeedback('皇后愈发伤心。<br>皇后宠爱 <span class="neg">-20</span>');
        }},
      ]);
    }else{
      showHonglouEvent('御史弹劾',[
        {text:'置之不理',effect:function(){
          showFeedback('置之不理，朝野议论纷纷。<br>声望有所下降。');
          logEvent('醉红楼','御史弹劾，皇上置之不理');
        }},
        {text:'贬官压制（500两）',effect:function(){
          if(state.treasury>=500){state.treasury-=500;showFeedback('贬了御史的官，平息了风波。<br>国库 <span class="neg">-500</span> 两');}
          else{showFeedback('国库空虚，拿不出500两……<br>只能置之不理了。');}
          logEvent('醉红楼','皇上贬官压制');
        }},
        {text:'下罪己诏',effect:function(){
          showFeedback('皇上自省，下月行动力 <span class="neg">-1</span>，但朝野渐渐平息。');
          logEvent('醉红楼','皇上罪己诏');
        }},
      ]);
    }
  }
  function showHonglouEvent(header,choices){
    document.getElementById('honglou-event-header').textContent=header;
    var html='<div style="padding:16px;">';
    if(header==='御史弹劾')html+='<div class="hl-reunion-scene">御史大夫上了一道奏折：<br>「皇上微服出入风月场所，恐有损圣名，望陛下三思。」</div>';
    else html+='<div class="hl-reunion-scene">听说皇上又去了醉红楼，<br>皇后摔了一只茶盏。</div>';
    choices.forEach(function(c,i){
      html+='<button class="hl-perf-btn" onclick="Game.honglouEventChoice('+i+')" style="margin-bottom:8px;">'+c.text+'</button>';
    });
    html+='</div>';
    document.getElementById('honglou-event-content').innerHTML=html;
    document.getElementById('honglou-event-actions').innerHTML='';
    state._honglouEventChoices=choices;
    document.getElementById('modal-honglou-event').classList.add('show');
  }
  function honglouEventChoice(idx){
    document.getElementById('modal-honglou-event').classList.remove('show');
    if(state._honglouEventChoices&&state._honglouEventChoices[idx]){
      state._honglouEventChoices[idx].effect();
    }
    state._honglouEventChoices=null;
    closeModal();
    if(state._honglou&&state._honglou.active){
      document.getElementById('honglou-treasury-info').textContent='国库：'+state.treasury+' 两';
    }
    save();
  }
  function closeHonglouEvent(){
    document.getElementById('modal-honglou-event').classList.remove('show');
    closeModal();
  }
  // 认亲剧情触发（在nextMonth中调用）
  function checkHonglouReunion(){
    if(!state.honglouPregnancies)return;
    for(var i=0;i<state.honglouPregnancies.length;i++){
      var p=state.honglouPregnancies[i];
      if(p.revealed)continue;
      var monthsSince=(state.year*12+state.month)-p.pregFrom;
      var triggerMonths=12+Math.floor(Math.random()*13); // 12-24个月
      if(monthsSince>=triggerMonths){
        triggerReunion(p);
        break;
      }
    }
  }
  function triggerReunion(p){
    p.revealed=true;
    var genderText=p.childGender==='male'?'小皇子':'小公主';
    var html='<div class="hl-reunion">';
    html+='<div class="hl-reunion-scene">';
    html+='太监来报：「启禀皇上，宫门外有一女子求见，说是……说是皇上的旧识。」<br><br>';
    html+='来者竟是两年前醉红楼的'+p.beautyName+'。<br>';
    html+='她身旁，还牵着一个'+genderText+'。<br><br>';
    html+=p.beautyName+'跪下，泪眼盈盈：<br>';
    html+='「皇上……这是您的骨肉啊。」<br><br>';
    html+=genderText+'怯生生地望向你，眉眼间竟与你有几分相似。<br>';
    html+='他/她忽然喊了一声：「'+(p.childGender==='male'?'父皇':'父皇')+'……」</div>';
    html+='<div class="hl-reunion-choices">';
    html+='<button class="hl-perf-btn" onclick="Game.reunionChoice(0)">泪目认下，接入宫中</button>';
    html+='<button class="hl-perf-btn secondary" onclick="Game.reunionChoice(1)">给银两千，安置宫外</button>';
    html+='<button class="hl-perf-btn secondary" onclick="Game.reunionChoice(2)">让她先回去，容后再议</button>';
    html+='</div></div>';
    document.getElementById('honglou-reunion-header').textContent='红楼认亲';
    document.getElementById('honglou-reunion-content').innerHTML=html;
    state._honglouReunionTarget=p;
    document.getElementById('modal-honglou-reunion').classList.add('show');
  }
  function reunionChoice(opt){
    var p=state._honglouReunionTarget;
    if(!p)return;
    p.decision=['adopt','dismiss','pending'][opt];
    if(opt===0){
      // 接入宫
      var genderText=p.childGender==='male'?'皇子':'皇女';
      var child={id:genId(),name:p.childName,gender:p.childGender,age:0,motherId:p.beautyId,motherName:p.beautyName,type:p.beautyData?p.beautyData.type:'',talent:rand(30,70),martial:rand(20,60),virtue:rand(40,80),prestige:0,health:rand(70,100),fromHonglou:true,adoptiveMotherId:null,adoptiveMotherName:null,isOrphan:false,orphanMonth:0,monthlyCost:0};
      state.children.push(child);
      // 母亲入宫
      if(p.beautyData){
        var initRank='答应';
        var pObj=p.beautyData.personality||PERSONALITIES[0];
        var concubine={id:genId(),name:p.beautyName,age:rand(17,25),beauty:rand(70,90),talent:rand(40,80),wisdom:rand(30,70),health:rand(80,100),favor:50,power:rand(5,15),rank:initRank,personality:pObj,trait:p.beautyData.trait||'温柔贤淑',family:{name:'醉红楼',initRank:initRank,color:'#c49030'},pregnant:false,pregMonth:0,portraitIdx:p.beautyData.portraitIdx||1,title:'',fromHonglou:true,honglouSkill:p.beautyData.type||'sing',portraitSeed:p.beautyData.portraitSeed||'',stress:0,stressCap:getStressCap(pObj.name),behaviorLog:[],_favored:false,favors:{},grudge:null,_flatterCount:0};
        state.concubines.push(concubine);
      }
      state.treasury-=200;
      logEvent('红楼认亲',p.beautyName+'带'+genderText+'入宫');
      showFeedback('<span class="pos">'+p.childName+'</span> 已接入宫中<br>封为<span class="pos">'+genderText+'</span>');
    }else if(opt===1){
      var money=rand(1000,2000);
      state.treasury-=money;
      if(!state.honglouOutsideFamily)state.honglouOutsideFamily=[];
      state.honglouOutsideFamily.push({beautyName:p.beautyName,childName:p.childName,childGender:p.childGender,childAge:0,yearlyCost:200,status:'outside'});
      logEvent('红楼认亲',p.beautyName+'被银两打发，'+p.childName+'养在宫外');
      showFeedback('给 '+money+' 两安置'+p.beautyName+'和'+p.childName+'在宫外<br>国库 <span class="neg">-'+money+'</span> 两');
    }else{
      logEvent('红楼认亲',p.beautyName+'暂且搁置');
      showFeedback('让'+p.beautyName+'先回去，此事容后再议。');
      p.revealed=false; // 允许再次触发
      p.decision='pending';
    }
    document.getElementById('modal-honglou-reunion').classList.remove('show');
    closeModal();
    updateUI();save();
  }
  function closeHonglouReunion(){
    document.getElementById('modal-honglou-reunion').classList.remove('show');
    closeModal();
  }
