  // 江南姓名池
  const JN_SURNAMES = [
    '沈','苏','顾','陆','白','柳','林','秦','楚','谢',
    '温','阮','叶','乔','江','何','萧','韩','洛','安'
  ];
  const JN_GIVEN_NAMES = [
    '婉清','如眉','若雪','青娥','绣儿','悠然','清辞','弄影','飞燕','芷若',
    '语嫣','灵芸','含烟','梦蝶','雨萱','清漪','晚晴','若兰','诗韵','凝香',
    '碧云','素心','雅琴','明月','流萤','秋蕊','霜华','翠微','晓月','念真',
    '思柔','静姝','曼吟','绮罗','锦瑟','琉璃','珊瑚','琉璃','芙蓉','海棠',
    '竹韵','梅影','兰心','菊芳','荷香','桃夭','柳絮','梨花','樱雪','杏雨'
  ];

  function genJiangnanName(){
    if(!state._usedJnNames)state._usedJnNames=[];
    var maxAttempts=100;
    for(var i=0;i<maxAttempts;i++){
      var sn=JN_SURNAMES[Math.floor(Math.random()*JN_SURNAMES.length)];
      var gn=JN_GIVEN_NAMES[Math.floor(Math.random()*JN_GIVEN_NAMES.length)];
      var fullName=sn+gn;
      if(state._usedJnNames.indexOf(fullName)===-1){
        state._usedJnNames.push(fullName);
        return fullName;
      }
    }
    var sn=JN_SURNAMES[Math.floor(Math.random()*JN_SURNAMES.length)];
    var gn=JN_GIVEN_NAMES[Math.floor(Math.random()*JN_GIVEN_NAMES.length)];
    return sn+gn+state._usedJnNames.length;
  }

  // 状态初始化
  function initJiangnan(){
    state._jiangnan = {active:false,actions:3,beauties:[],explored:{boat:0,market:0,teahouse:0,outing:0},currentEvent:null,done:false};
  }

  function showJiangnanStart(){
    if(state.jiangnanYear===state.year){showFeedback('今年已经下过江南了！');return;}
    if(state.treasury<2000){showFeedback('国库不足，需2000两！');return;}
    if(state.actionsLeft<3){showFeedback('本月行动不足3次，无法出远门！');return;}
    var html='<div style="padding:16px;">';
    html+='<div style="font-size:14px;color:#5a3e28;line-height:1.8;text-align:center;margin-bottom:14px;">';
    html+='「皇上可要下江南寻美？此行需耗费国库银两，且需数日方可往返。」</div>';
    html+='<div style="background:rgba(255,245,230,0.6);border-radius:8px;padding:12px;font-size:13px;color:#5a3e28;line-height:2;">';
    html+='<div>&#128176; 国库消耗：<b>2000两</b></div>';
    html+='<div>&#128197; 行动消耗：<b>3次</b></div>';
    html+='<div>&#128111; 可遇佳人：<b>3~5位</b></div>';
    html+='</div></div>';
    html+='<div style="display:flex;gap:8px;padding:0 16px 16px;">';
    html+='<button onclick="Game.startJiangnan()" class="btn-primary" style="flex:1;">&#127752; 出发</button>';
    html+='<button onclick="Game.closeJnStart()" style="flex:1;padding:12px;border:1px solid rgba(200,160,80,0.3);border-radius:10px;background:rgba(255,250,240,0.8);color:#a08060;font-size:14px;font-family:inherit;font-weight:bold;cursor:pointer;">取消</button>';
    html+='</div>';
    document.getElementById('jn-start-content').innerHTML=html;
    document.getElementById('modal-jn-start').classList.add('show');
  }

  function startJiangnan(){
    state.treasury-=2000;
    state.actionsLeft-=3;
    state.jiangnanYear=state.year;
    initJiangnan();
    state._jiangnan.active=true;
    document.getElementById('modal-jn-start').classList.remove('show');
    closeModal();
    showJiangnan();
    save();updateUI();
  }

  function showJiangnan(){
    document.getElementById('page-jiangnan').classList.add('active');
    // Hide banner since page uses background image now
    var banner=document.querySelector('.jn-banner');
    if(banner) banner.style.display='none';
    updateJnLocations();
    updateJnStatus();
  }

  function closeJiangnan(){
    document.getElementById('page-jiangnan').classList.remove('active');
    if(state._jiangnan&&state._jiangnan.active){
      state._jiangnan.active=false;
      state._jiangnan=null;
    }
    closeOut();
    save();updateUI();
  }

  function updateJnStatus(){
    var jn=state._jiangnan;
    if(!jn)return;
    document.getElementById('jn-actions-left').textContent='剩余行动：'+jn.actions;
    var recruited=jn.beauties.filter(function(b){return b.recruited;}).length;
    document.getElementById('jn-encounters').textContent='已遇：'+recruited+'/'+jn.beauties.length;
  }

  function updateJnLocations(){
    var jn=state._jiangnan;
    var grid=document.getElementById('jn-locations-grid');
    var html='';
    JN_LOCATIONS.forEach(function(loc){
      var explored=jn.explored[loc.id]||0;
      var cls='jn-location-card';
      var status='可探索';
      var onclick='';
      if(explored===0){
        if(jn.actions<=0){cls+=' locked';status='行动不足';onclick='';}
        else{onclick="Game.exploreLocation('"+loc.id+"')";status='可探索';}
      }else if(explored===1){
        var hasHarvest=jn.beauties.some(function(b){return b.location===loc.id;});
        if(hasHarvest){cls+=' harvest';status='已有收获';}
        else{cls+=' locked';status='暂无收获';}
        if(jn.actions>0){onclick="Game.exploreLocation('"+loc.id+"')";status='再探一次';}
        else{status='行动不足';}
      }else{
        cls+=' locked';status='已无新意';
      }
      html+='<div class="'+cls+'" onclick="'+onclick+'">';
      html+='<div class="jn-loc-icon">'+loc.icon+'</div>';
      html+='<div class="jn-loc-name">'+loc.name+'</div>';
      html+='<div class="jn-loc-desc">'+loc.desc+'</div>';
      html+='<div class="jn-loc-status">'+status+'</div>';
      html+='</div>';
    });
    grid.innerHTML=html;
  }

  function exploreLocation(locId){
    var jn=state._jiangnan;
    if(!jn||jn.actions<=0)return;
    jn.actions--;
    jn.explored[locId]=(jn.explored[locId]||0)+1;
    // Pick random event from location
    var pool=JN_BEAUTIES.filter(function(b){return b.location===locId;});
    var beauty=pick(pool);
    var favor=rand(5,15);
    var rndName=genJiangnanName();
    var beautyState={id:beauty.id,name:rndName,age:beauty.age,personality:beauty.personality,beauty:rand(beauty.beauty[0],beauty.beauty[1]),talent:rand(beauty.talent[0],beauty.talent[1]),wisdom:rand(beauty.wisdom[0],beauty.wisdom[1]),trait:beauty.trait,portraitIdx:pickPortrait(),favor:favor,recruited:false,_templateName:beauty.name};
    // Check if already recruited
    var existing=jn.beauties.find(function(b){return b.id===beauty.id;});
    if(existing){
      // Already met this beauty
      showJnEventAlreadyMet(existing);
    }else{
      jn.beauties.push(beautyState);
      showJnEvent(beautyState,beauty);
    }
    save();
  }

  function showJnEvent(bs,beauty){
    state._jnCurrentBeauty=bs;
    state._jnCurrentBeautyTemplate=beauty;
    renderJnEventScene(bs,beauty);
    document.getElementById('modal-jn-event').classList.add('show');
  }

  function showJnEventAlreadyMet(bs){
    var html='<div style="padding:16px;text-align:center;">';
    html+='<div style="font-size:16px;color:#c49030;font-weight:bold;margin-bottom:8px;">&#128522; 再次相遇</div>';
    html+='<div style="font-size:14px;color:#5a3e28;line-height:1.8;">'+bs.name+' 见到你，眼中闪过一丝惊喜：「大人，又见面了。」</div>';
    html+='<div style="font-size:13px;color:#a08060;margin-top:10px;">当前好感度：'+bs.favor+'</div>';
    html+='</div>';
    html+='<div style="display:flex;gap:8px;padding:0 16px 16px;">';
    if(bs.favor>=50){
      html+='<button onclick="Game.confirmRecruit()" class="jn-btn gold" style="flex:1;">&#128111; 带回后宫</button>';
    }
    html+='<button onclick="Game.closeJnEvent()" class="jn-btn secondary" style="flex:1;">离去</button>';
    html+='</div>';
    document.getElementById('jn-event-header').innerHTML='&#27743;&#21335;&#23547;&#32654;';
    document.getElementById('jn-event-content').innerHTML=html;
    document.getElementById('jn-event-actions').innerHTML='';
    document.getElementById('modal-jn-event').classList.add('show');
  }

  function renderJnEventScene(bs,beauty){
    var tName=beauty.name;
    var rName=bs.name;
    var intro=rName!==tName?beauty.intro.split(tName).join(rName):beauty.intro;
    var html='<div style="padding:14px 16px;">';
    html+='<div style="font-size:13px;color:#c49030;font-weight:bold;margin-bottom:8px;">&#127752; '+rName+'</div>';
    html+='<div class="jn-event-scene">'+intro+'</div>';
    // Portrait
    html+='<div class="jn-event-portrait">';
    html+=portraitHTML(bs.portraitIdx,120,150,'');
    html+='<div class="jn-event-name">'+bs.name+'</div>';
    html+='<div class="jn-event-info">'+bs.age+'岁 · '+bs.personality+' · '+bs.trait+'</div>';
    html+='</div>';
    // Favor bar
    var favorPct=Math.min(100,bs.favor);
    var favorColor=favorPct>=50?'#c49030':favorPct>=25?'#e0a040':'#d0d0d0';
    html+='<div style="font-size:11px;color:#8a7060;">好感度</div>';
    html+='<div class="jn-favor-bar"><div class="jn-favor-fill" style="width:'+favorPct+'%;background:'+favorColor+';"></div></div>';
    html+='</div>';
    document.getElementById('jn-event-header').innerHTML='&#127752; '+rName;
    document.getElementById('jn-event-content').innerHTML=html;
    // Actions
    var acts=document.getElementById('jn-event-actions');
    var actHtml='<div class="jn-actions">';
    actHtml+='<button onclick="Game.jnTalk()" class="jn-btn">&#128172; 交谈</button>';
    actHtml+='<button onclick="Game.jnGift()" class="jn-btn">&#127873; 赠礼</button>';
    if(bs.favor>=50){
      actHtml+='<button onclick="Game.confirmRecruit()" class="jn-btn gold">&#128111; 带回后宫</button>';
    }else{
      actHtml+='<button onclick="Game.closeJnEvent()" class="jn-btn secondary">离去</button>';
    }
    actHtml+='</div>';
    acts.innerHTML=actHtml;
  }

  function jnTalk(){
    var bs=state._jnCurrentBeauty;
    var beauty=state._jnCurrentBeautyTemplate;
    if(!bs||!beauty)return;
    var dIdx=bs._dialogueIdx||0;
    if(dIdx<beauty.dialogue.length){
      var d=beauty.dialogue[dIdx];
      bs._dialogueIdx=dIdx+1;
      bs.favor=clamp(bs.favor+10,0,100);
      var tN=beauty.name;var rN=bs.name;
      var sTxt=rN!==tN?d.s.split(tN).join(rN):d.s;
      var rTxt=rN!==tN?d.r.split(tN).join(rN):d.r;
      var html='<div style="padding:14px 16px;">';
      html+='<div class="jn-dialogue">'+sTxt+'</div>';
      html+='<div class="jn-dialogue" style="border-left-color:#9060c0;">'+rTxt+'</div>';
      html+='<div style="font-size:12px;color:#4caf50;text-align:center;margin:8px 0;">好感度 +10（当前：'+bs.favor+'）</div>';
      html+='</div>';
      document.getElementById('jn-event-content').innerHTML=html;
      // Update actions
      var acts=document.getElementById('jn-event-actions');
      var actHtml='<div class="jn-actions">';
      if(dIdx+1<beauty.dialogue.length){
        actHtml+='<button onclick="Game.jnTalk()" class="jn-btn">&#128172; 继续交谈（+10好感）</button>';
      }else{
        actHtml+='<button onclick="Game.jnTalk()" class="jn-btn" disabled style="opacity:0.4;">&#128172; 已无更多对话</button>';
      }
      actHtml+='<button onclick="Game.jnGift()" class="jn-btn">&#127873; 赠礼</button>';
      if(bs.favor>=50){
        actHtml+='<button onclick="Game.confirmRecruit()" class="jn-btn gold">&#128111; 带回后宫</button>';
      }else{
        actHtml+='<button onclick="Game.closeJnEvent()" class="jn-btn secondary">离去</button>';
      }
      actHtml+='</div>';
      acts.innerHTML=actHtml;
      save();
    }
  }

  function jnGift(){
    var bs=state._jnCurrentBeauty;
    if(!bs)return;
    var html='<div style="padding:14px 16px;">';
    html+='<div style="font-size:13px;color:#8a7060;margin-bottom:10px;text-align:center;">皇上想赠予 '+bs.name+' 何物？</div>';
    html+='<div class="jn-gift-grid">';
    JN_GIFTS.forEach(function(g,i){
      var dis=state.treasury<g.cost?'style="opacity:0.4;pointer-events:none;"':'';
      html+='<div class="jn-gift-item" onclick="Game.giveJnGift('+i+')" '+dis+'>';
      html+='<div class="jn-gift-icon">'+g.icon+'</div>';
      html+='<div style="flex:1;"><div class="jn-gift-name">'+g.name+'</div><div class="jn-gift-desc">国库 -'+g.cost+'两 | 好感 +'+g.favor+'</div></div>';
      html+='</div>';
    });
    html+='</div></div>';
    html+='<div style="padding:0 16px 16px;"><button onclick="Game.closeJnGift()" class="jn-btn secondary" style="width:100%;">取消</button></div>';
    document.getElementById('jn-gift-content').innerHTML=html;
    document.getElementById('modal-jn-gift').classList.add('show');
  }

  function giveJnGift(idx){
    var g=JN_GIFTS[idx];
    if(state.treasury<g.cost){showFeedback('国库不足！');return;}
    var bs=state._jnCurrentBeauty;
    if(!bs)return;
    state.treasury-=g.cost;
    bs.favor=clamp(bs.favor+g.favor,0,100);
    document.getElementById('modal-jn-gift').classList.remove('show');
    // Re-render event scene
    var beauty=state._jnCurrentBeautyTemplate;
    if(beauty)renderJnEventScene(bs,beauty);
    // Show gift result
    var html='<div style="padding:14px 16px;">';
    html+='<div style="text-align:center;margin-bottom:10px;">';
    html+='<div style="font-size:28px;">'+g.icon+'</div>';
    html+='<div style="font-size:14px;color:#5a3e28;font-weight:bold;margin-top:4px;">'+bs.name+' 收下了 '+g.name+'</div>';
    html+='<div style="font-size:13px;color:#4caf50;margin-top:6px;">好感度 +'+g.favor+'（当前：'+bs.favor+'）</div>';
    html+='</div></div>';
    var acts=document.getElementById('jn-event-actions');
    var actHtml='<div class="jn-actions">';
    actHtml+='<button onclick="Game.jnTalk()" class="jn-btn">&#128172; 交谈</button>';
    actHtml+='<button onclick="Game.jnGift()" class="jn-btn">&#127873; 继续赠礼</button>';
    if(bs.favor>=50){
      actHtml+='<button onclick="Game.confirmRecruit()" class="jn-btn gold">&#128111; 带回后宫</button>';
    }else{
      actHtml+='<button onclick="Game.closeJnEvent()" class="jn-btn secondary">离去</button>';
    }
    actHtml+='</div>';
    acts.innerHTML=actHtml;
    document.getElementById('jn-event-content').innerHTML=html;
    save();updateUI();
  }

  function confirmRecruit(){
    var bs=state._jnCurrentBeauty;
    var beauty=state._jnCurrentBeautyTemplate;
    if(!bs)return;
    // Determine rank and power based on family origin
    var jnFam=beauty?beauty.jnFamily:'平民';
    var jnRank,jnPowerMin,jnPowerMax;
    if(jnFam==='名门'){jnRank='贵人';jnPowerMin=55;jnPowerMax=70;}
    else if(jnFam==='寒门'){jnRank='常在';jnPowerMin=35;jnPowerMax=50;}
    else{jnRank='官女子';jnPowerMin=3;jnPowerMax=10;}
    var html='<div style="padding:16px;">';
    html+='<div style="font-size:14px;color:#5a3e28;text-align:center;margin-bottom:14px;">确定将 <b style="color:#c49030;">'+bs.name+'</b> 带回后宫吗？</div>';
    html+='<div class="jn-event-portrait">';
    html+=portraitHTML(bs.portraitIdx,100,130,'');
    html+='<div class="jn-event-name">'+bs.name+'</div>';
    html+='<div class="jn-event-info">'+bs.age+'岁 · '+bs.personality+'</div>';
    html+='</div>';
    html+='<div class="jn-recruit-info" style="text-align:center;margin:10px 0;">';
    html+='<div>美貌：<b style="color:#e06080;">'+bs.beauty+'</b></div>';
    html+='<div>才华：<b style="color:#6080e0;">'+bs.talent+'</b></div>';
    html+='<div>智慧：<b style="color:#40a080;">'+bs.wisdom+'</b></div>';
    html+='<div>特长：<b style="color:#c49030;">'+bs.trait+'</b></div>';
    html+='<div>出身：<b style="color:#806030;">江南'+jnFam+'</b></div>';
    html+='<div>初始位份：<b>'+jnRank+'</b></div>';
    html+='</div>';
    html+='</div>';
    html+='<div style="display:flex;gap:8px;padding:0 16px 16px;">';
    html+='<button onclick="Game.doRecruit()" class="jn-btn gold" style="flex:1;">&#128111; 确认带回</button>';
    html+='<button onclick="Game.closeJnRecruit()" class="jn-btn secondary" style="flex:1;">再考虑</button>';
    html+='</div>';
    document.getElementById('jn-recruit-content').innerHTML=html;
    document.getElementById('modal-jn-recruit').classList.add('show');
  }

  function doRecruit(){
    var bs=state._jnCurrentBeauty;
    var beauty=state._jnCurrentBeautyTemplate;
    if(!bs)return;
    // Determine rank and power based on family origin
    var jnFam=beauty?beauty.jnFamily:'平民';
    var jnRank,jnPowerMin,jnPowerMax,jnFamilyDesc;
    if(jnFam==='名门'){jnRank='贵人';jnPowerMin=55;jnPowerMax=70;jnFamilyDesc='江南名门望族';}
    else if(jnFam==='寒门'){jnRank='常在';jnPowerMin=35;jnPowerMax=50;jnFamilyDesc='江南寒门士族';}
    else{jnRank='官女子';jnPowerMin=3;jnPowerMax=10;jnFamilyDesc='江南民间';}
    var initPower=rand(jnPowerMin,jnPowerMax);
    // Create concubine entry
    var pname=bs.personality;
    var pObj=PERSONALITIES.find(function(p){return p.name===pname;})||PERSONALITIES[0];
    var c={
      id:genId(),name:bs.name,age:bs.age,
      beauty:bs.beauty,talent:bs.talent,wisdom:bs.wisdom,
      trait:bs.trait,favor:30,power:initPower,health:rand(70,90),
      rank:jnRank,pregnant:false,pregMonth:0,
      portraitIdx:bs.portraitIdx,
      personality:pObj,
      family:{name:jnFamilyDesc,desc:'江南'+jnFam+'入宫',weight:1,initRank:jnRank,color:'#6a5a4a'},
      title:'',fromJiangnan:true,jnFamily:jnFam,
      stress:0,stressCap:getStressCap(pObj.name),
      behaviorLog:[],_favored:false,favors:{},grudge:null,_flatterCount:0
    };
    state.concubines.push(c);
    bs.recruited=true;
    logEvent('江南寻美',bs.name+'被带回后宫');
    document.getElementById('modal-jn-recruit').classList.remove('show');
    document.getElementById('modal-jn-event').classList.remove('show');
    closeJnEvent();
    save();updateUI();
    showFeedback('<b style="color:#c49030;">&#128111; '+bs.name+' 已入后宫</b><br>出身：江南'+jnFam+'<br>位份：'+jnRank+'<br>势力：'+initPower+'<br>性格：'+bs.personality);
    // Refresh Jiangnan page
    updateJnLocations();
    updateJnStatus();
  }

  function closeJnStart(){document.getElementById('modal-jn-start').classList.remove('show');}
  function closeJnEvent(){document.getElementById('modal-jn-event').classList.remove('show');state._jnCurrentBeauty=null;state._jnCurrentBeautyTemplate=null;}
  function closeJnGift(){document.getElementById('modal-jn-gift').classList.remove('show');}
  function closeJnRecruit(){document.getElementById('modal-jn-recruit').classList.remove('show');}

  // ===== 立后大典 =====
  // 家族下诏文本
  const CORONATION_DECREE = {
    noble: { // 顶级世家
      text: '奉天承运，皇帝诏曰：{family}氏 {name}，钟灵毓秀，淑德昭彰。朕承天恩，特册立为皇后，母仪天下，钦此——',
      desc: '圣旨由礼部尚书宣诏，{family} 族人跪伏接旨，族中长老热泪盈眶，感慨门楣光耀。'
    },
    mid: { // 中等家族
      text: '奉天承运，皇帝诏曰：{name} 秉性端良，温婉贤淑。特册立为皇后，统领六宫，钦此——',
      desc: '宣旨太监高唱圣，{family} 族人恭敬接旨，族人互视颔首，欣喜之情溢于言表。'
    },
    low: { // 寒微之家
      text: '奉天承运，皇帝诏曰：{name} 淑慎性成，勤勉柔顺。特册立为皇后，以正位中宫，钦此——',
      desc: '宣旨声落，宫中窃语纷纷。{family} 名不见经传，此番破格立后，朝野震动。'
    }
  };
  // 性格仪态文本
  const CORONATION_DEMEANOR = {
    gentle: [ // 温柔善良系
      '她身着正红色凤冠霞帔，步履从容，凤冠上的珠翠随步伐轻轻摇曳。跪拜天地时神色肃穆，眼中隐有泪光——那是压抑已久的激动与感慨。'
    ],
    coquettish: [ // 娇媚系
      '她一袭正红礼服，明眸流转，嘴角含笑。受百官朝贺时悄悄抬眼看向皇上方向，眼波盈盈，难掩雀跃之色。'
    ],
    dignified: [ // 端庄系
      '她仪态万方，凤冠华服，端坐凤椅之上，神色庄重。接受六宫朝拜时微微颔首，举手投足间已隐隐有母仪天下之风。'
    ],
    scheming: [ // 心机系
      '她凤冠华服，端坐凤椅之上，嘴角勾起一抹若有似无的笑意。低垂的眼眸深处闪烁着志得意满的光芒——那些曾轻看她的人，如今都要向她叩首了。'
    ],
    cold: [ // 清冷系
      '她面无表情地受完所有仪程，凤冠下的脸庞始终平静如水。旁人看来是端庄沉稳，只有她自己知道，心中并无波澜。'
    ],
    weak: [ // 柔弱系
      '她双手微颤地接过凤印，眼眶泛红。向皇上叩首时声音哽咽：「臣妾……臣妾定不负皇上厚爱……」'
    ],
    wise: [ // 智慧型
      '她仪态端庄，举止合度，每一道仪程都分毫不差。礼部尚书暗自点头——这位新后虽年轻，却已有母仪天下之风。'
    ],
    talented: [ // 才情系
      '她举止间自带一股清雅气质，凤冠霞帔也难掩那份出尘之姿。乐师奏乐时她微微侧耳，眼中流露出对音律的熟稔。'
    ],
    secular: [ // 世俗系
      '她身着正红色凤冠霞帔，凤冠上的珠翠熠熠生辉。她嘴角含笑，享受着万众瞩目的时刻。'
    ]
  };
  function getDecreeTier(family){
    if(!family)return 'low';
    const n=family.name||'';
    if(['宗室王族','国公世家','一品文臣','一品武将','侯爵世家'].some(x=>n.includes(x)))return 'noble';
    if(['二品文臣','二品武将','伯爵世家','三品文臣','三品武将','四品朝臣','四品武将'].some(x=>n.includes(x)))return 'mid';
    return 'low';
  }
  function getDemeanorGroup(pname){
    if(['温婉','温柔体恤','娴静恬淡','慈悲良善','贤淑'].includes(pname))return 'gentle';
    if(['明艳魅惑','娇媚','娇俏灵动','风情婉约'].includes(pname))return 'coquettish';
    if(['端庄','端庄大气','严谨守礼','贵气凛然'].includes(pname))return 'dignified';
    if(['心机','城府深沉','狠戾果决','伪善假面','野心勃勃'].includes(pname))return 'scheming';
    if(['清冷','冷清疏离','傲骨清高','淡薄无欲','冷艳寡言'].includes(pname))return 'cold';
    if(['柔弱楚楚','黏人依赖','偏执痴迷'].includes(pname))return 'weak';
    if(['聪慧博闻','沉稳睿智'].includes(pname))return 'wise';
    if(['精通乐艺','清雅脱俗','文雅诗意'].includes(pname))return 'talented';
    if(['爱吃贪趣','小气善妒','虚荣攀比','多疑敏感','阴郁寡欢','直率爽朗','桀骜不羁','刚烈执拗','活泼'].includes(pname))return 'secular';
    return 'gentle';
  }
  function getRivalReaction(rival){
    if(!rival)return '其余妃嫔依次上前，奉茶叩首，六宫秩序由此而定。';
    const rp=rival.personality?rival.personality.name:'温婉';
    if(['心机','城府深沉','伪善假面'].includes(rp))return rival.rank+rival.name+' 微笑上前奉茶叩首：「臣妾恭贺皇后娘娘——」笑容温婉，眼底却暗藏算计。';
    if(['小气善妒','野心勃勃','狠戾果决'].includes(rp))return rival.rank+rival.name+' 跪伏在地，声音僵硬：「臣妾……恭贺皇后娘娘。」低垂的眼中难掩不甘与嫉恨。';
    if(['清雅脱俗','冷清疏离','淡薄无欲'].includes(rp))return rival.rank+rival.name+' 上前叩首：「恭喜娘娘。」神色淡淡，不卑不亢。';
    if(['温婉','温柔体恤','娴静恬淡','贤淑'].includes(rp))return rival.rank+rival.name+' 诚心祝贺，上前奉茶叩首：「臣妾恭贺皇后娘娘，愿娘娘凤体安康。」';
    return rival.rank+rival.name+' 上前叩首：「臣妾恭贺皇后娘娘。」';
  }

  function triggerEmpressEvent(c){
    // Find rival: second highest power concubine (excluding cold palace)
    var sorted=state.concubines.filter(function(x){return x.id!==c.id&&x.rank!=='皇后';}).sort(function(a,b){return(b.power||0)-(a.power||0);});
    var rival=sorted.length>0?sorted[0]:null;
    state._coronationTarget=c.id;
    state._coronationRival=rival?rival.id:null;
    // Block normal actions, show coronation event
    state.pendingEvent={type:'coronation',targetId:c.id};
    save();updateUI();
    showCoronationEvent(c,rival);
  }

  function showCoronationEvent(c,rival){
    var rivalText=rival?rival.rank+rival.name:'后宫无其他人选';
    var html='<div style="padding:16px 0;">';
    html+='<div style="background:rgba(255,245,230,0.6);border-left:3px solid #c49030;padding:14px 16px;margin-bottom:16px;font-size:14px;line-height:1.8;color:#5a3e28;">';
    html+='「启禀皇上，<b style="color:#c49030;">'+c.rank+c.name+'</b> 近来势力日盛，朝中已有大臣联名上奏，建议立 '+c.name+' 为皇后。';
    if(rival)html+='<b style="color:#9060c0;">'+rivalText+'</b> 暗中联络母家，似有争后之意。';
    html+='六宫无主，恐生事端，请皇上定夺。」</div>';
    // Portrait
    html+=portraitHTML(c.portraitIdx,140,180,c.princessPortrait);
    html+='<div style="text-align:center;font-size:16px;font-weight:bold;color:#c49030;margin-top:8px;">'+c.rank+' '+c.name+'</div>';
    html+='<div style="text-align:center;font-size:12px;color:#a08060;">'+(c.personality?c.personality.name:'')+' · 势力 '+(c.power||0)+'</div>';
    html+='</div>';
    document.getElementById('coronation-header').innerHTML='&#20998;&#21300;&#20043;&#20105;';
    document.getElementById('coronation-content').innerHTML=html;
    var acts=document.getElementById('coronation-actions');
    var dis=state.actionsLeft<=0?'disabled':'';
    acts.innerHTML='<div style="display:flex;flex-direction:column;gap:8px;">'+
      '<button onclick="Game.confirmEmpress(1)" '+dis+' style="padding:12px;border:1px solid rgba(200,160,80,0.5);border-radius:10px;background:linear-gradient(180deg,rgba(210,180,100,0.5),rgba(190,160,80,0.5));color:#8a6020;font-size:14px;font-family:inherit;font-weight:bold;cursor:pointer;">&#128081; 立 '+c.name+' 为后（进入立后大典）</button>'+
      (rival?'<button onclick="Game.confirmEmpress(2)" '+dis+' style="padding:12px;border:1px solid rgba(144,96,192,0.4);border-radius:10px;background:rgba(255,250,240,0.8);color:#6040a0;font-size:14px;font-family:inherit;font-weight:bold;cursor:pointer;">&#9878;&#65039; 暂不立后，平衡两方</button>':'')+
      (rival?'<button onclick="Game.confirmEmpress(3)" '+dis+' style="padding:12px;border:1px solid rgba(200,160,80,0.5);border-radius:10px;background:linear-gradient(180deg,rgba(210,180,100,0.5),rgba(190,160,80,0.5));color:#8a6020;font-size:14px;font-family:inherit;font-weight:bold;cursor:pointer;">&#128081; 立 '+rival.name+' 为后（进入立后大典）</button>':'')+
      '<button onclick="Game.confirmEmpress(4)" '+dis+' style="padding:12px;border:1px solid rgba(160,160,160,0.3);border-radius:10px;background:rgba(255,250,240,0.6);color:#808080;font-size:14px;font-family:inherit;font-weight:bold;cursor:pointer;">&#128164; 都不立，先冷处理</button>'+
      '</div>';
    document.getElementById('modal-coronation').classList.add('show');
  }

  function confirmEmpress(choice){
    var c=state.concubines.find(function(x){return x.id===state._coronationTarget;});
    var rival=state._coronationRival?state.concubines.find(function(x){return x.id===state._coronationRival;}):null;
    if(!c){closeCoronation();return;}
    document.getElementById('modal-coronation').classList.remove('show');
    if(choice===1){
      // 立 c 为后
      c.rank='皇后';c.power=clamp(c.power,321,500);
      logEvent('立后',c.name+'被册立为皇后');
      save();updateUI();
      showCoronationCeremony(c);
    }else if(choice===2){
      // 平衡两方
      c.power=clamp(c.power-20,0,500);
      if(rival)rival.power=clamp((rival.power||0)+20,0,500);
      state._coronationCooldown=c.id;
      save();updateUI();
      var msg='皇上暂不立后，平衡两方<br>'+c.name+' 势力 <span class="neg">-20</span>';
      if(rival)msg+='<br>'+rival.name+' 势力 <span class="pos">+20</span>';
      showFeedback(msg);
      state.pendingEvent=null;state._coronationTarget=null;state._coronationRival=null;
      closeModal();
    }else if(choice===3&&rival){
      // 立 rival 为后
      rival.rank='皇后';rival.power=clamp(rival.power||0,321,500);
      c.power=clamp(c.power-50,0,500);
      // Force rank check for c
      checkRankChange(c);
      logEvent('立后',rival.name+'被册立为皇后');
      save();updateUI();
      showCoronationCeremony(rival);
    }else if(choice===4){
      // 冷处理
      c.power=clamp(c.power-10,0,500);
      if(rival)rival.power=clamp((rival.power||0)-10,0,500);
      state._coronationCooldown=c.id;
      save();updateUI();
      var msg='皇上冷处理此事<br>'+c.name+' 势力 <span class="neg">-10</span>';
      if(rival)msg+='<br>'+rival.name+' 势力 <span class="neg">-10</span>';
      showFeedback(msg);
      state.pendingEvent=null;state._coronationTarget=null;state._coronationRival=null;
      closeModal();
    }
  }

  function showCoronationCeremony(queen){
    state._coronationAct=0;
    state._coronationQueenId=queen.id;
    showCoronationAct(queen);
  }

  function showCoronationAct(queen){
    var act=state._coronationAct;
    var acts=document.getElementById('coronation-actions');
    var content=document.getElementById('coronation-content');
    var header=document.getElementById('coronation-header');
    var actTitles=['&#128221; 下旨册封','&#127897; 大典仪式','&#128274; 凤印交接','&#128115; 六宫朝贺','&#127881; 大典落幕'];
    var pname=queen.personality?queen.personality.name:'温婉';
    var dgroup=getDemeanorGroup(pname);
    var tier=getDecreeTier(queen.family);
    var decree=CORONATION_DECREE[tier];
    var fname=queen.family?queen.family.name:'平民';
    var qname=queen.name;
    var rival=state._coronationRival?state.concubines.find(function(x){return x.id===state._coronationRival;}):null;

    if(act===0){
      // 第一幕：下旨册封
      header.innerHTML='&#128221; 下旨册封';
      var html='<div style="padding:8px 0;">';
      html+='<div style="background:linear-gradient(135deg,rgba(255,220,180,0.3),rgba(255,200,150,0.15));border:1px solid rgba(200,160,80,0.3);border-radius:10px;padding:16px;margin-bottom:14px;">';
      html+='<div style="font-size:15px;font-weight:bold;color:#8a6020;text-align:center;margin-bottom:12px;letter-spacing:2px;">&#22857; &#21629;</div>';
      html+='<div style="font-size:14px;color:#5a3e28;line-height:2;text-indent:2em;">'+decree.text.replace(/\{name\}/g,qname).replace(/\{family\}/g,fname)+'</div>';
      html+='</div>';
      html+='<div style="font-size:13px;color:#806040;line-height:1.8;text-indent:2em;">'+decree.desc.replace(/\{family\}/g,fname)+'</div>';
      html+='</div>';
      content.innerHTML=html;
      acts.innerHTML='<div style="text-align:center;"><button onclick="Game.nextCoronationAct()" class="btn-primary">下一页</button></div>';
    }else if(act===1){
      // 第二幕：大典仪式
      header.innerHTML='&#127897; 大典仪式';
      var demeanor=CORONATION_DEMEANOR[dgroup]||CORONATION_DEMEANOR.gentle;
      var html='<div style="padding:8px 0;">';
      html+='<div style="background:linear-gradient(135deg,rgba(255,100,100,0.15),rgba(255,220,180,0.15));border:1px solid rgba(200,80,80,0.25);border-radius:10px;padding:16px;margin-bottom:14px;">';
      html+='<div style="font-size:14px;color:#5a3e28;line-height:2;text-indent:2em;">'+demeanor[0]+'</div>';
      html+='</div>';
      html+='<div style="font-size:13px;color:#806040;line-height:1.8;text-indent:2em;">礼乐声中，'+qname+' 缓步走向太和殿，接受文武百官朝贺。正红色的礼服在阳光下熠熠生辉，凤冠上的明珠折射出夺目光彩。</div>';
      html+='</div>';
      content.innerHTML=html;
      acts.innerHTML='<div style="text-align:center;"><button onclick="Game.nextCoronationAct()" class="btn-primary">下一页</button></div>';
    }else if(act===2){
      // 第三幕：凤印交接
      header.innerHTML='&#128274; 凤印交接';
      var html='<div style="padding:8px 0;">';
      html+='<div style="background:linear-gradient(135deg,rgba(255,215,0,0.15),rgba(255,200,150,0.15));border:1px solid rgba(200,160,80,0.3);border-radius:10px;padding:16px;margin-bottom:14px;">';
      html+='<div style="font-size:14px;color:#5a3e28;line-height:2;text-indent:2em;">礼部尚书奉上凤印——金质盘龙钮，重三斤六两，上刻「皇后之宝」四字。<br>'+qname+' 双手接过凤印，高高举起。<br>「臣妾 '+qname+'，恭受凤印，愿以中正之心，统御六宫，辅佐皇上，绵延国祚。」<br>钟鼓齐鸣，百官跪拜，三呼万岁。</div>';
      html+='</div>';
      html+='</div>';
      content.innerHTML=html;
      acts.innerHTML='<div style="text-align:center;"><button onclick="Game.nextCoronationAct()" class="btn-primary">下一页</button></div>';
    }else if(act===3){
      // 第四幕：六宫朝贺
      header.innerHTML='&#128115; 六宫朝贺';
      var rivalReaction=getRivalReaction(rival);
      var html='<div style="padding:8px 0;">';
      html+='<div style="background:linear-gradient(135deg,rgba(200,160,255,0.12),rgba(255,220,240,0.12));border:1px solid rgba(160,100,200,0.2);border-radius:10px;padding:16px;margin-bottom:14px;">';
      html+='<div style="font-size:14px;color:#5a3e28;line-height:2;text-indent:2em;">'+rivalReaction+'</div>';
      html+='</div>';
      // Show other concubines reactions
      var others=state.concubines.filter(function(x){return x.id!==queen.id&&x.rank!=='皇后';});
      if(others.length>0){
        var show=Math.min(2,others.length);
        for(var i=0;i<show;i++){
          var oc=others[i];var op=oc.personality?oc.personality.name:'温婉';
          var react='';
          if(['心机','城府深沉','伪善假面'].includes(op))react=' 微笑上前奉茶，眼底暗藏算计';
          else if(['小气善妒','野心勃勃'].includes(op))react=' 勉强跪拜，面色难看';
          else if(['清雅脱俗','冷清疏离'].includes(op))react=' 上前叩首，神色淡淡';
          else react=' 上前奉茶叩首，态度恭敬';
          html+='<div style="font-size:12px;color:#806040;line-height:1.8;padding:4px 0;text-indent:2em;">'+oc.rank+oc.name+react+'。</div>';
        }
      }
      html+='</div>';
      content.innerHTML=html;
      acts.innerHTML='<div style="text-align:center;"><button onclick="Game.nextCoronationAct()" class="btn-primary">下一页</button></div>';
    }else if(act===4){
      // 第五幕：大典落幕
      header.innerHTML='&#127881; 大典落幕';
      var html='<div style="padding:8px 0;">';
      html+='<div style="background:linear-gradient(135deg,rgba(255,200,100,0.15),rgba(255,240,200,0.1));border:1px solid rgba(200,160,80,0.25);border-radius:10px;padding:16px;margin-bottom:14px;">';
      html+='<div style="font-size:14px;color:#5a3e28;line-height:2;text-indent:2em;">大典持续至日落方歇。<br>'+qname+' 端坐坤宁宫凤座之上，凤冠已卸，但凤印仍置于案前。<br>窗外灯火通明，六宫张灯结彩。<br><br><b style="color:#c49030;">新的后宫格局，就此确立。</b></div>';
      html+='</div>';
      html+='</div>';
      content.innerHTML=html;
      acts.innerHTML='<div style="text-align:center;"><button onclick="Game.finishCoronation()" class="btn-primary" style="background:linear-gradient(180deg,rgba(210,180,100,0.6),rgba(190,160,80,0.6));color:#8a6020;">&#127881; 礼成</button></div>';
    }

    document.getElementById('modal-coronation').classList.add('show');
  }

  function nextCoronationAct(){
    var queen=state.concubines.find(function(x){return x.id===state._coronationQueenId;});
    if(!queen){closeCoronation();return;}
    state._coronationAct++;
    showCoronationAct(queen);
  }

  function finishCoronation(){
    document.getElementById('modal-coronation').classList.remove('show');
    state.pendingEvent=null;
    state._coronationTarget=null;
    state._coronationRival=null;
    state._coronationQueenId=null;
    state._coronationAct=0;
    state._coronationCooldown=null;state._coronationSelectId=null;
    closeModal();
    save();updateUI();
    // Show feedback
    var queen=state.concubines.find(function(x){return x.id===state._coronationQueenId;});
    var qname=queen?queen.name:'新后';
    showFeedback('<b style="color:#c49030;">&#128081; '+qname+' 正式册立为皇后</b><br>凤印已交，六宫朝贺，新后入主坤宁宫。');
  }

  function closeCoronation(){
    document.getElementById('modal-coronation').classList.remove('show');
    closeModal();
  }

  // ===== 手动册立皇后 =====
  function openCoronationSelect(){
    if(state.concubines.length===0){showFeedback('后宫空无一人，无法册立皇后');return;}
    if(state.actionsLeft<=0){showFeedback('本月行动已用完');return;}
    if(state.treasury<3000){showFeedback('国库不足3000两，无法册立皇后');return;}
    if(state.concubines.find(x=>x.rank==='皇后')){showFeedback('已有皇后，无需册立');return;}
    state._coronationSelectId=null;
    renderCoronationSelectModal();
    document.getElementById('modal-coronation-select').classList.add('show');
  }

  function renderCoronationSelectModal(){
    var sorted=state.concubines.slice().sort(function(a,b){return(b.power||0)-(a.power||0);});
    var html='<div style="padding:12px 16px;">';
    html+='<p style="color:#8a7060;font-size:13px;margin-bottom:12px;text-align:center;">请皇上挑选册立人选：</p>';
    sorted.forEach(function(c){
      var hp=c.health>=70?'#4caf50':c.health>=40?'#ff9800':'#e55555';
      var isSelected=state._coronationSelectId===c.id;
      var needsBoost=(c.power||0)<321;
      html+='<div class="concubine-card" onclick="Game.selectCoronationCandidate(\''+c.id+'\')" style="'+(isSelected?'border-color:#d49030;background:rgba(255,240,220,0.95);':'')+'">';
      html+=portraitHTML(c.portraitIdx,60,75,c.princessPortrait);
      html+='<div class="concubine-info">';
      html+='<div class="concubine-name">'+c.rank+' '+c.name+(isSelected?' <span style="color:#d49030;font-size:11px;">&#10003;</span>':'')+'</div>';
      html+='<div class="concubine-stats">';
      html+='<span>&#21183;&#21147; <b style="color:#9060c0;">'+(c.power||0)+'</b></span>';
      html+='<span>&#20581;&#24247; <b style="color:'+hp+'">'+c.health+'</b></span></div>';
      if(needsBoost)html+='<div style="font-size:11px;color:#c04040;margin-top:4px;">&#9888;&#65039; &#21183;&#21147;&#19981;&#36275;&#30343;&#20301;&#65292;&#20876;&#31435;&#21518;&#23558;&#33258;&#21160;&#34917;&#36275;&#33267; 321</div>';
      html+='</div></div>';
    });
    html+='</div>';
    html+='<div style="display:flex;gap:8px;padding:12px 16px 16px;">';
    html+='<button onclick="Game.closeCoronationSelect()" style="flex:1;padding:12px;border:1px solid rgba(200,160,80,0.3);border-radius:10px;background:rgba(255,250,240,0.8);color:#a08060;font-size:14px;font-family:inherit;font-weight:bold;cursor:pointer;">&#21462;&#28040;</button>';
    var dis=!state._coronationSelectId?'disabled':'';
    html+='<button id="cor-confirm-btn" onclick="Game.confirmCoronationManual()" '+dis+' style="flex:1;padding:12px;border:1px solid rgba(200,160,80,0.5);border-radius:10px;background:linear-gradient(180deg,rgba(210,180,100,0.5),rgba(190,160,80,0.5));color:#8a6020;font-size:14px;font-family:inherit;font-weight:bold;cursor:pointer;letter-spacing:2px;">&#30830;&#35748;&#20876;&#31435;</button>';
    html+='</div>';
    document.getElementById('coronation-select-content').innerHTML=html;
  }

  function selectCoronationCandidate(id){
    state._coronationSelectId=state._coronationSelectId===id?null:id;
    renderCoronationSelectModal();
    var btn=document.getElementById('cor-confirm-btn');
    if(btn)btn.disabled=!state._coronationSelectId;
  }

  function confirmCoronationManual(){
    var c=findC(state._coronationSelectId);
    if(!c)return;
    if(state.concubines.find(function(x){return x.rank==='皇后';})){
      showFeedback('&#24050;&#26377;&#30343;&#21518;&#65292;&#26080;&#38656;&#20876;&#31435;');closeCoronationSelect();return;
    }
    if(state.treasury<3000){showFeedback('&#22269;&#24211;&#19981;&#36275;3000&#19976;&#65292;&#26080;&#27861;&#20876;&#31435;');closeCoronationSelect();return;}
    if(state.actionsLeft<=0){showFeedback('&#26412;&#26376;&#34892;&#21160;&#24050;&#29992;&#23436;');closeCoronationSelect();return;}
    state.actionsLeft--;
    state.treasury-=3000;
    // &#21183;&#21147;&#34917;&#36275;
    if((c.power||0)<321)c.power=321;
    c.rank='皇后';c.power=clamp(c.power,321,500);
    logEvent('册立皇后',c.name+'被皇上亲自册立为皇后');
    save();updateUI();
    closeCoronationSelect();
    showCoronationCeremony(c);
  }

  function closeCoronationSelect(){
    document.getElementById('modal-coronation-select').classList.remove('show');
    closeModal();
  }

