  // 治国理政状态
  var _govState = {questions:[],currentIdx:0,correctCount:0,answered:false};

  function openGovernance(){
    var govDone=state._governanceLastMonth===(state.year*12+state.month);
    if(govDone){showFeedback('本月已经答过治国理政了，下月再来！');return;}
    // Pick 5 random questions
    var shuffled=GOV_QUESTIONS.slice().sort(function(){return 0.5-Math.random();});
    _govState.questions=shuffled.slice(0,5);
    _govState.currentIdx=0;
    _govState.correctCount=0;
    _govState.answered=false;
    renderGovQuestion();
    document.getElementById('modal-governance').classList.add('show');
  }

  function renderGovQuestion(){
    var qi=_govState.currentIdx;
    var total=5;
    if(qi>=total){showGovSummary();return;}
    var q=_govState.questions[qi];
    _govState.answered=false;
    var html='<div style="text-align:center;font-size:12px;color:#a08060;margin-bottom:12px;">第 '+(qi+1)+' / '+total+' 题</div>';
    html+='<div class="gov-question">'+q.q+'</div>';
    html+='<div id="gov-options">';
    var letters=['A','B','C','D'];
    q.opts.forEach(function(opt,i){
      html+='<div class="gov-option" id="gov-opt-'+i+'" onclick="Game.selectGovAnswer('+i+')"><span class="gov-letter">'+letters[i]+'</span>'+opt+'</div>';
    });
    html+='</div>';
    html+='<div id="gov-feedback" style="display:none;"></div>';
    html+='<div style="text-align:center;margin-top:16px;">';
    html+='<button id="gov-next-btn" class="gov-btn gov-btn-next" style="display:none;" onclick="Game.nextGovQuestion()">下一题</button>';
    html+='</div>';
    document.getElementById('governance-content').innerHTML=html;
    document.getElementById('gov-modal-title').innerHTML='&#128220; 治国理政';
  }

  function selectGovAnswer(idx){
    if(_govState.answered)return;
    _govState.answered=true;
    var q=_govState.questions[_govState.currentIdx];
    var isCorrect=idx===q.ans;
    if(isCorrect)_govState.correctCount++;
    // Highlight options
    var letters=['A','B','C','D'];
    for(var i=0;i<4;i++){
      var el=document.getElementById('gov-opt-'+i);
      if(!el)continue;
      if(i===q.ans){el.className='gov-option correct';}
      else if(i===idx&&!isCorrect){el.className='gov-option wrong';}
      el.style.cursor='default';
    }
    // Show feedback
    var fb=document.getElementById('gov-feedback');
    var resultText=isCorrect?'✅ 回答正确！ +500两':'❌ 回答错误！';
    var resultCls=isCorrect?'gov-result-text correct':'gov-result-text wrong';
    var html='<div class="'+resultCls+'">'+resultText+'</div>';
    html+='<div class="gov-explanation"><b>&#128218; 解析：</b>'+q.expl+'</div>';
    fb.innerHTML=html;
    fb.style.display='block';
    // Show next button
    document.getElementById('gov-next-btn').style.display='inline-block';
  }

  function nextGovQuestion(){
    _govState.currentIdx++;
    if(_govState.currentIdx>=5){
      showGovSummary();
    }else{
      renderGovQuestion();
    }
  }

  function showGovSummary(){
    var score=_govState.correctCount;
    var reward=score*500;
    var html='<div class="gov-summary">';
    html+='<div style="font-size:20px;color:#5a3e28;margin-bottom:6px;">&#128220; 治国理政 · 答卷</div>';
    html+='<div class="gov-summary-score">'+score+' / 5</div>';
    html+='<div style="font-size:14px;color:#8a7060;margin-bottom:12px;">答对 '+score+' 题</div>';
    if(reward>0){
      html+='<div class="gov-summary-reward">&#128176; 获得 '+reward+' 两</div>';
      state.treasury+=reward;
      // Record the month
      state._governanceLastMonth=state.year*12+state.month;
    }else{
      html+='<div style="font-size:14px;color:#a08060;margin:8px 0;">再接再厉，下月继续！</div>';
      state._governanceLastMonth=state.year*12+state.month;
    }
    html+='<div style="margin-top:16px;">';
    html+='<button class="gov-btn gov-btn-next" onclick="Game.closeGovernance()">确 定</button>';
    html+='</div></div>';
    document.getElementById('governance-content').innerHTML=html;
    document.getElementById('gov-modal-title').innerHTML='&#128220; 治国理政 · 完成';
    save();updateUI();
  }

  function closeGovernance(){
    document.getElementById('modal-governance').classList.remove('show');
    closeModal();
  }

