(function(){
  // Debug: verify Game is defined
  var dbg = document.getElementById('debug-status');
  if(dbg) dbg.innerHTML = 'Game type: ' + typeof Game;
  if(typeof Game === 'undefined'){
    if(dbg) dbg.innerHTML += ' | ERROR: Game not defined!';
    return;
  }
  try{
    Game.init();
    if(dbg) dbg.innerHTML += ' | Init OK';
  }catch(e){
    if(dbg) dbg.innerHTML += ' | Init Error: ' + e.message;
    alert('Game init error: ' + e.message);
  }
})();
window.onerror = function(msg, url, line, col, err){
  alert('JS Error: '+msg+'\nLine: '+line);
  return false;
};
